CREATE OR REPLACE FUNCTION private.advance_notification_preference_revision()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if tg_op = 'INSERT' then
    new.revision := 0;
    new.incarnation := gen_random_uuid();
  else
    if new.user_id is distinct from old.user_id then
      raise exception 'notification_preference_subject_immutable' using errcode = '22023';
    end if;
    if old.revision = 9223372036854775807 then
      raise exception 'notification_preference_revision_exhausted' using errcode = '22003';
    end if;
    new.revision := old.revision + 1;
    new.incarnation := old.incarnation;
  end if;
  return new;
end $function$

CREATE OR REPLACE FUNCTION private.assert_notification_preference_session()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if not coalesce(public.whole_app_exact_current_session_authority_internal(), false)
    or not exists (
      select 1 from auth.sessions s
      where s.id::text = auth.jwt()->>'session_id' and s.user_id = auth.uid()
        and (s.not_after is null or s.not_after > clock_timestamp())
    ) then
    raise exception 'notification_preference_current_session_required' using errcode = '42501';
  end if;
  -- A retained snapshot cannot recheck authority revoked during a lock wait.
  if current_setting('transaction_isolation') <> 'read committed' then
    raise exception 'notification_preference_requires_read_committed' using errcode = '25000';
  end if;
end $function$

CREATE OR REPLACE FUNCTION private.bind_broadcast_notification_room()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare r public.watch_party_rooms;
begin
  if tg_op='UPDATE' then
    if (new.notification_room_id,new.notification_room_generation,new.notification_room_host)
      is distinct from (old.notification_room_id,old.notification_room_generation,old.notification_room_host)
      then raise exception 'broadcast_notification_binding_immutable'; end if;
    return new;
  end if;
  new.notification_room_id:=null;new.notification_room_generation:=null;new.notification_room_host:=null;
  if new.source_type<>'watch_party_room' then return new; end if;
  select * into r from public.watch_party_rooms
    where party_id=coalesce(nullif(new.source_room_id,''),nullif(new.watch_party_room_id,'')) for share;
  if r.party_id is not null and r.host_user_id=private.discovery_notification_uuid(coalesce(new.host_user_id,new.channel_user_id))
    and not exists(select 1 from private.creator_event_broadcast_preparations p where p.party_id=r.party_id) then
    new.notification_room_id:=r.party_id;new.notification_room_generation:=r.room_generation;
    new.notification_room_host:=r.host_user_id;
  end if;
  return new;
end $function$

CREATE OR REPLACE FUNCTION private.bind_room_start_notification_candidate()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare r public.watch_party_rooms;s jsonb;t text:=new.context->>'sourceType';
begin
  if new.event_kind not in ('followed_creator_live','circle_friend_live') or t not in ('live_stage','party_room','broadcast')
    then return new; end if;
  s:=case when t='party_room' then private.party_room_notification_source(new.source_id)
    else private.discovery_notification_source(t,new.source_id) end;
  if s->>'eligible' is distinct from 'true' or s->>'owner' is distinct from new.actor_user_id::text
    or s->>'revision' is distinct from new.context->>'revision' or s->>'audience' is distinct from new.context->>'audience'
    then return new; end if;
  select * into r from public.watch_party_rooms where party_id=case when t='broadcast' then s->>'target_entity_id' else new.source_id end for share;
  if r.party_id is null or not r.is_active or r.host_user_id is distinct from new.actor_user_id
    or exists(select 1 from private.creator_event_broadcast_preparations p where p.party_id=r.party_id) then return new; end if;
  insert into private.room_start_notification_bindings(event_id,party_id,room_generation,host_user_id,recipient_user_id,
    source_type,source_id,source_revision,source_audience,event_kind)
    values(new.id,r.party_id,r.room_generation,r.host_user_id,new.recipient_user_id,t,new.source_id,s->>'revision',s->>'audience',new.event_kind);
  return new;
end $function$

CREATE OR REPLACE FUNCTION private.discovery_notification_event_visible(e creator_events, p_user uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare pass public.paid_creator_event_passes; identity jsonb;
begin
  if e.status='draft' then return false; end if;
  if e.visibility='public' then return true; end if;
  if e.visibility='circle' then return public.is_active_chilly_circle_member(e.host_user_id::text,p_user::text); end if;
  if e.visibility<>'private' then return false; end if;
  select * into pass from public.paid_creator_event_passes p
    where p.creator_event_id=e.id and p.creator_id=e.host_user_id and p.buyer_id=p_user
      and p.status='active' and p.revoked_at is null and p.refunded_at is null and p.access_grant_id is not null
      and (p.expires_at is null or p.expires_at>now()) order by p.created_at desc limit 1;
  if not found then return false; end if;
  begin
    identity:=public.creator_money_historical_purchase_identity_internal(p_user,'event_pass',e.id,pass.access_grant_id);
  exception when raise_exception then
    if sqlerrm='historical_purchase_identity_missing' then return false; end if;
    raise;
  end;
  return coalesce(private.discovery_notification_uuid(identity->>'accessGrantId')=pass.access_grant_id,false);
end;
$function$

CREATE OR REPLACE FUNCTION private.discovery_notification_source(p_type text, p_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare result jsonb;b public.room_broadcast_sessions;r public.watch_party_rooms;
begin
  result:=private.discovery_notification_source_pre_room_start_binding(p_type,p_id);
  if result->>'eligible'='true' and p_type='broadcast' then
    select * into b from public.room_broadcast_sessions where id=private.discovery_notification_uuid(p_id);
    select * into r from public.watch_party_rooms where party_id=result->>'target_entity_id';
    -- Event-managed private transport retains its separate preparation and
    -- provider-operation authority; this is only the ordinary start lane.
    if not exists(select 1 from private.creator_event_broadcast_preparations p where p.party_id=r.party_id
      and p.broadcast_session_id=b.id and p.creator_event_id::text=b.creator_event_id and p.host_user_id=r.host_user_id
      and p.host_user_id::text=b.host_user_id)
      and (b.notification_room_id is distinct from r.party_id or b.notification_room_generation is distinct from r.room_generation
        or b.notification_room_host is distinct from r.host_user_id or b.notification_room_generation is null)
      then return '{"eligible":false}'; end if;
  end if;
  return result;
end $function$

CREATE OR REPLACE FUNCTION private.discovery_notification_source_pre_listing_pause(p_type text, p_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare source jsonb; r public.watch_party_rooms;
begin
  source:=private.discovery_notification_source_pre_room_visibility(p_type,p_id);
  if source->>'eligible' is distinct from 'true' then return source; end if;
  if p_type in ('live_stage','broadcast') then
    select * into r from public.watch_party_rooms where party_id=case when p_type='live_stage' then p_id else source->>'target_entity_id' end;
    if not found or not r.is_active or r.discovery_visibility not in ('public','circle')
      or r.discovery_visibility is distinct from source->>'audience'
      then return '{"eligible":false}'; end if;
    if p_type='live_stage' then
      if not private.live_stage_publication_current(r.party_id) then return '{"eligible":false}'; end if;
      source:=source||jsonb_build_object('revision',r.room_generation);
    end if;
  end if;
  return source;
end $function$

CREATE OR REPLACE FUNCTION private.discovery_notification_source_pre_room_start_binding(p_type text, p_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare result jsonb;
begin
  result:=private.discovery_notification_source_pre_listing_pause(p_type,p_id);
  if result->>'eligible'='true' and p_type in ('live_stage','broadcast') and exists(
    select 1 from public.watch_party_rooms r where party_id=case when p_type='live_stage' then p_id else result->>'target_entity_id' end
      and discovery_paused and not exists(select 1 from private.creator_event_broadcast_preparations p where p.party_id=r.party_id))
    then return '{"eligible":false}'; end if;
  return result;
end $function$

CREATE OR REPLACE FUNCTION private.discovery_notification_source_pre_room_visibility(p_type text, p_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare r public.watch_party_rooms; b public.room_broadcast_sessions;
  h public.spectator_hls_playback_records; v public.videos; x public.creator_replay_library_items;
  owner_id uuid; audience text; revision text; route text; entity text; title_text text;
begin
  if p_type='live_stage' then
    select * into r from public.watch_party_rooms where party_id=p_id;
    if not found or r.room_type<>'live' or not r.is_active or r.discovery_started_at is null
      or r.content_access_rule<>'open'
      or exists(select 1 from public.paid_live_watch_party_offers o where o.party_id=r.party_id
        and o.pass_type='live_watch_party_access_pass' and o.status not in ('canceled','ended'))
      or r.discovery_visibility not in ('public','circle') then return '{"eligible":false}'; end if;
    owner_id:=r.host_user_id; audience:=r.discovery_visibility;
    revision:=r.discovery_started_at::text;
    route:='/watch-party/live-stage/[partyId]'; entity:=r.party_id; title_text:='Live now';
  elsif p_type='broadcast' then
    select * into b from public.room_broadcast_sessions where id=private.discovery_notification_uuid(p_id);
    if not found then return '{"eligible":false}'; end if;
    select * into h from public.spectator_hls_playback_records where broadcast_session_id=b.id;
    if not found or b.broadcast_status<>'active_later' or b.ended_at is not null
      or not b.is_spectator_playback_enabled or b.requires_premium or b.requires_ticket
      or b.rights_status not in ('creator_owned','chillywood_original','licensed_for_public_stream')
      or b.metadata->>'spectator_child_room_fixture'='true'
      or h.playback_status<>'live' or not h.is_spectator_playback_enabled or h.playlist_path is null
      or h.requires_premium or h.requires_ticket
      or h.rights_status not in ('creator_owned','chillywood_original','licensed_for_public_stream')
    then return '{"eligible":false}'; end if;
    if b.access_type='public_free' and b.playback_url_status='public_safe_available'
      and b.is_publicly_watchable and b.metadata->>'d7f_public_safe_approved'='true'
      and h.visibility='public' and h.access_type='public_free' and h.is_publicly_watchable
    then audience:='public';
    elsif b.access_type='circle' and b.playback_url_status='circle_safe_available'
      and not b.is_publicly_watchable and b.metadata->>'circle_spectator_approved'='true'
      and h.visibility='circle' and h.access_type='circle' and not h.is_publicly_watchable
    then audience:='circle'; else return '{"eligible":false}'; end if;
    owner_id:=private.discovery_notification_uuid(coalesce(b.host_user_id,b.channel_user_id));
    entity:=coalesce(nullif(b.source_room_id,''),nullif(b.watch_party_room_id,''));
    select * into r from public.watch_party_rooms where party_id=entity;
    if not found or not r.is_active or r.host_user_id is distinct from owner_id
      or h.source_room_id is distinct from entity then return '{"eligible":false}'; end if;
    revision:=b.id::text; route:='/watch-party/[partyId]'; title_text:='Watch-Party live now';
  elsif p_type='video' then
    select * into v from public.videos where id=private.discovery_notification_uuid(p_id);
    if not found or not coalesce(private.discovery_notification_video_public(v),false) then return '{"eligible":false}'; end if;
    owner_id:=v.owner_id; audience:='public'; revision:=v.id::text;
    route:='/player/[id]'; entity:=v.id::text; title_text:='New public upload';
  elsif p_type='replay' then
    select * into x from public.creator_replay_library_items where id=private.discovery_notification_uuid(p_id);
    if not found or x.save_status<>'ready' or x.visibility not in ('public','circle')
      or x.moderation_status not in ('clean','reported') or x.money_status<>'free'
      or x.rights_status not in ('creator_owned','chillywood_original','licensed_for_public_stream')
      or x.playback_record_id is null then return '{"eligible":false}'; end if;
    select * into h from public.spectator_hls_playback_records where id=x.playback_record_id;
    if not found or h.requires_premium or h.requires_ticket or h.playback_status not in ('live','ended')
      or h.host_user_id is distinct from x.owner_user_id or h.visibility<>x.visibility
      or h.rights_status not in ('creator_owned','chillywood_original','licensed_for_public_stream')
      or not h.is_spectator_playback_enabled then return '{"eligible":false}'; end if;
    select * into b from public.room_broadcast_sessions where id=h.broadcast_session_id;
    if not found or x.broadcast_session_id is distinct from b.id or b.host_user_id is distinct from x.owner_user_id
      or b.requires_premium or b.requires_ticket
      or b.access_type not in ('public_free','circle')
      or b.rights_status not in ('creator_owned','chillywood_original','licensed_for_public_stream')
      or coalesce(b.hls_playback_url,'') !~ '^https://[^[:space:]]+\.m3u8($|[?#])'
    then return '{"eligible":false}'; end if;
    if not b.is_spectator_playback_enabled or (
      (x.visibility='public' and h.access_type='public_free' and h.is_publicly_watchable
        and b.access_type='public_free' and b.is_publicly_watchable
        and b.playback_url_status='public_safe_available' and b.metadata->>'d7f_public_safe_approved'='true')
      or (x.visibility='circle' and h.access_type='circle' and not h.is_publicly_watchable
        and b.access_type='circle' and not b.is_publicly_watchable
        and b.playback_url_status='circle_safe_available' and b.metadata->>'circle_spectator_approved'='true')
    ) is not true then return '{"eligible":false}'; end if;
    owner_id:=private.discovery_notification_uuid(x.owner_user_id); audience:=x.visibility;
    revision:=x.id::text||':'||x.playback_record_id::text;
    route:='/player/replay/[replayId]'; entity:=x.id::text; title_text:='Replay is ready';
  else return '{"eligible":false}'; end if;
  if owner_id is null or not exists(select 1 from auth.users where id=owner_id)
    or public.is_account_access_restricted(owner_id::text) then return '{"eligible":false}'; end if;
  return jsonb_build_object('eligible',true,'owner',owner_id,'audience',audience,'revision',revision,
    'target_route',route,'target_entity_id',entity,'title',title_text);
end $function$

CREATE OR REPLACE FUNCTION private.enqueue_discovery_notification_transition()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare reminder public.event_reminders;
begin
  if tg_table_name='watch_party_rooms' then
    if tg_op='INSERT' or (new.is_active,new.discovery_started_at,new.discovery_visibility)
      is distinct from (old.is_active,old.discovery_started_at,old.discovery_visibility) then
      perform private.enqueue_discovery_notification_source('live_stage',new.party_id); end if;
  elsif tg_table_name='room_broadcast_sessions' then
    if tg_op='INSERT' or (to_jsonb(new)-'updated_at'-'last_health_checked_at')
      is distinct from (to_jsonb(old)-'updated_at'-'last_health_checked_at') then
      perform private.enqueue_discovery_notification_source('broadcast',new.id::text); end if;
  elsif tg_table_name='spectator_hls_playback_records' then
    if tg_op='INSERT' or (to_jsonb(new)-'updated_at') is distinct from (to_jsonb(old)-'updated_at') then
      perform private.enqueue_discovery_notification_source('broadcast',new.broadcast_session_id::text); end if;
  elsif tg_table_name='videos' then
    if tg_op='INSERT' or not coalesce(private.discovery_notification_video_public(old),false) then
      perform private.enqueue_discovery_notification_source('video',new.id::text); end if;
  elsif tg_table_name='creator_replay_library_items' then
    if tg_op='INSERT' or (new.save_status,new.visibility,new.playback_record_id,new.rights_status,new.moderation_status,new.money_status)
      is distinct from (old.save_status,old.visibility,old.playback_record_id,old.rights_status,old.moderation_status,old.money_status) then
      perform private.enqueue_discovery_notification_source('replay',new.id::text); end if;
  elsif tg_table_name='event_reminders' then
    if tg_op='INSERT' or (new.status,new.event_id,new.user_id) is distinct from (old.status,old.event_id,old.user_id) then
      perform private.enqueue_discovery_event_reminder(new); end if;
  elsif tg_table_name='creator_events' then
    if tg_op='UPDATE' and private.discovery_notification_event_revision(new)
      is distinct from private.discovery_notification_event_revision(old) then
      for reminder in select * from public.event_reminders where event_id=new.id and status='active' loop
        perform private.enqueue_discovery_event_reminder(reminder,old.status in ('scheduled','live_now'));
      end loop;
    end if;
  end if;
  return new;
end $function$

CREATE OR REPLACE FUNCTION private.enqueue_moderation_notification_activity()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_target jsonb;
begin
  if new.status<>'actioned' or (old.status=new.status and old.resolution_type is not distinct from new.resolution_type
    and old.resolved_at is not distinct from new.resolved_at) then return new; end if;
  v_target:=private.notification_moderation_target(new);
  if v_target is null then return new; end if;
  perform private.enqueue_notification_activity('moderation-decision:'||new.id::text||':'||new.resolved_at::text||':'||new.resolution_type,
    'moderation_notice',new.id::text,null,(v_target->>'owner')::uuid,
    jsonb_build_object('resolution',new.resolution_type,'resolvedAt',new.resolved_at));
  return new;
end $function$

CREATE OR REPLACE FUNCTION private.enqueue_party_room_notification(p_party_id text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare s jsonb:=private.party_room_notification_source(p_party_id); who record; owner_id uuid; kind text;
begin
  if s->>'eligible' is distinct from 'true' then return; end if;
  owner_id:=private.discovery_notification_uuid(s->>'owner');
  for who in with recipients as (
    select f.follower_user_id as id from public.channel_followers f where s->>'audience'='public' and f.channel_user_id=owner_id::text
    union select case when f.user_low_id=owner_id::text then f.user_high_id else f.user_low_id end
      from public.user_friendships f where f.status='active' and owner_id::text in (f.user_low_id,f.user_high_id)
  ) select u.id,public.is_active_chilly_circle_member(owner_id::text,u.id::text) as friend
    from recipients c join auth.users u on u.id=private.discovery_notification_uuid(c.id)
    where u.id<>owner_id and private.party_room_metadata_allowed(p_party_id,u.id,s->>'audience')
  loop
    kind:=case when who.friend then 'circle_friend_live' else 'followed_creator_live' end;
    perform private.enqueue_notification_activity('discovery:party_room:'||p_party_id||':'||(s->>'revision')||':'||who.id,
      kind,p_party_id,owner_id,who.id,jsonb_build_object('sourceType','party_room','revision',s->>'revision','audience',s->>'audience'),
      now(),now()+interval '10 minutes');
  end loop;
end $function$

CREATE OR REPLACE FUNCTION private.enqueue_social_notification_activity()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_new jsonb:=to_jsonb(new); v_old jsonb; v_actor uuid; v_recipient uuid;
  v_kind text; v_source text; v_context jsonb:='{}'; v_rec record;
  v_owner text; v_parent text; v_other text;
  v_key_suffix text:='';
begin
  if tg_op='UPDATE' then v_old:=to_jsonb(old); end if;
  if tg_table_name='channel_followers' then
    v_actor:=private.social_notification_uuid(new.follower_user_id);
    v_recipient:=private.social_notification_uuid(new.channel_user_id);
    v_kind:='social_follow'; v_source:=new.channel_user_id||':'||new.follower_user_id;
    v_context:=jsonb_build_object('followedAt',new.followed_at);
  elsif tg_table_name='channel_audience_requests' then
    if new.request_kind<>'follow' then return new; end if;
    v_source:=new.id::text;
    v_context:=jsonb_build_object('channelUserId',new.channel_user_id,'requesterUserId',new.requester_user_id,'createdAt',new.created_at);
    if tg_op='INSERT' and new.status='pending' then
      v_kind:='social_follow_request';
      v_actor:=private.social_notification_uuid(new.requester_user_id);
      v_recipient:=private.social_notification_uuid(new.channel_user_id);
    elsif tg_op='UPDATE' and old.status='pending' and new.status='approved'
      and old.channel_user_id=new.channel_user_id and old.requester_user_id=new.requester_user_id then
      v_kind:='social_follow_accepted';
      v_actor:=private.social_notification_uuid(new.channel_user_id);
      v_recipient:=private.social_notification_uuid(new.requester_user_id);
    else return new; end if;
  elsif tg_table_name='user_friendships' then
    v_actor:=private.social_notification_uuid(new.requested_by_user_id);
    v_other:=case when new.requested_by_user_id=new.user_low_id then new.user_high_id else new.user_low_id end;
    v_recipient:=private.social_notification_uuid(v_other);
    v_source:=new.user_low_id||':'||new.user_high_id;
    -- The request RPC advances created_at after removal, decline or cancellation.
    -- Keep one event per real request lifecycle, independent of session timezone.
    v_key_suffix:=':lifecycle:'||extract(epoch from new.created_at)::text;
    v_context:=jsonb_build_object('requestedBy',new.requested_by_user_id,'createdAt',new.created_at,'respondedAt',new.responded_at);
    if new.status='pending' and (tg_op='INSERT' or old.status is distinct from 'pending' or old.requested_by_user_id is distinct from new.requested_by_user_id) then
      v_kind:='circle_request';
    elsif new.status='active' and (tg_op='INSERT' or old.status is distinct from 'active') then
      if tg_op='UPDATE' and old.status='pending' and old.requested_by_user_id=new.requested_by_user_id and new.actioned_by_user_id=v_other then
        v_kind:='circle_accepted'; v_recipient:=v_actor; v_actor:=private.social_notification_uuid(v_other);
      elsif new.actioned_by_user_id=new.requested_by_user_id then v_kind:='circle_added';
      else return new; end if;
    else return new; end if;
  elsif tg_table_name in ('user_content_relationships','profile_posts') then
    if tg_table_name='user_content_relationships' then
      if new.relationship_type<>'share' then return new; end if;
      v_kind:='content_shared'; v_source:=new.title_id; v_actor:=private.social_notification_uuid(new.user_id);
      v_context:=jsonb_build_object('titleId',new.title_id);
    else
      if new.deleted_at is not null or new.visibility<>'public' or new.moderation_status<>'clean'
        or (tg_op='UPDATE' and old.deleted_at is null and old.visibility='public' and old.moderation_status in ('clean','reported'))
      then return new; end if;
      v_kind:='circle_post'; v_source:=new.id::text; v_actor:=private.social_notification_uuid(new.user_id);
      v_context:=jsonb_build_object('postId',new.id,'createdAt',new.created_at);
    end if;
    for v_rec in select case when user_low_id=v_actor::text then user_high_id else user_low_id end as user_id
      from public.user_friendships where status='active' and v_actor::text in (user_low_id,user_high_id)
    loop
      v_recipient:=private.social_notification_uuid(v_rec.user_id);
      if private.social_notification_accounts_allowed(v_actor,v_recipient) then
        perform private.enqueue_notification_activity(v_kind||':'||v_source||':'||v_actor||':'||v_recipient,v_kind,v_source,v_actor,v_recipient,v_context);
      end if;
    end loop;
    return new;
  elsif tg_table_name='profile_post_likes' then
    select user_id into v_owner from public.profile_posts where id=new.post_id;
    v_kind:='profile_post_liked'; v_source:=new.post_id::text;
    v_actor:=private.social_notification_uuid(new.user_id); v_recipient:=private.social_notification_uuid(v_owner);
    v_context:=jsonb_build_object('postId',new.post_id,'createdAt',new.created_at);
  elsif tg_table_name in ('profile_post_comments','creator_video_comments') then
    if new.deleted_at is not null or new.moderation_status<>'clean' then return new; end if;
    v_actor:=private.social_notification_uuid(new.user_id); v_source:=new.id::text;
    if tg_table_name='profile_post_comments' then
      select user_id into v_owner from public.profile_posts where id=new.post_id;
      select user_id into v_parent from public.profile_post_comments where id=new.parent_comment_id and post_id=new.post_id and deleted_at is null and moderation_status in ('clean','reported');
      v_context:=jsonb_build_object('postId',new.post_id,'parentCommentId',new.parent_comment_id,'createdAt',new.created_at);
    else
      select owner_id::text into v_owner from public.videos where id=new.video_id;
      select user_id into v_parent from public.creator_video_comments where id=new.parent_comment_id and video_id=new.video_id and deleted_at is null and moderation_status in ('clean','reported');
      v_context:=jsonb_build_object('videoId',new.video_id,'parentCommentId',new.parent_comment_id,'createdAt',new.created_at);
    end if;
    for v_rec in select distinct user_id from (values(v_owner),(v_parent)) recipients(user_id) where user_id is not null loop
      v_recipient:=private.social_notification_uuid(v_rec.user_id);
      v_kind:=(case when tg_table_name='profile_post_comments' then 'profile_' else 'video_' end)
        ||case when v_rec.user_id=v_parent then 'reply' else 'comment' end;
      if private.social_notification_accounts_allowed(v_actor,v_recipient) then
        perform private.enqueue_notification_activity('comment:'||tg_table_name||':'||v_source||':'||v_recipient,v_kind,v_source,v_actor,v_recipient,v_context);
      end if;
    end loop;
    return new;
  elsif tg_table_name='chat_messages' then
    if new.moderation_status<>'clean' or new.message_type<>'text' then return new; end if;
    v_kind:='chat_message'; v_source:=new.id::text; v_actor:=private.social_notification_uuid(new.sender_user_id);
    v_context:=jsonb_build_object('threadId',new.thread_id,'createdAt',new.created_at);
    for v_rec in select user_id from public.chat_thread_members where thread_id=new.thread_id and user_id<>new.sender_user_id loop
      v_recipient:=private.social_notification_uuid(v_rec.user_id);
      if private.social_notification_accounts_allowed(v_actor,v_recipient) then
        perform private.enqueue_notification_activity(v_kind||':'||v_source||':'||v_recipient,v_kind,v_source,v_actor,v_recipient,v_context);
      end if;
    end loop;
    return new;
  else return new; end if;
  if private.social_notification_accounts_allowed(v_actor,v_recipient) then
    perform private.enqueue_notification_activity(v_kind||':'||v_source||':'||v_actor||':'||v_recipient||v_key_suffix,v_kind,v_source,v_actor,v_recipient,v_context);
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION private.hold_sandbox_cashout_changed_merch()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare source_id uuid; c uuid;
begin
 source_id:=case when tg_op='DELETE' then old.id else new.id end;
 for c in select distinct e.creator_id from private.sandbox_cashout_executions e
  join private.sandbox_cashout_merch_allocations a on a.execution_id=e.id where a.order_id=source_id order by e.creator_id loop
  perform pg_advisory_xact_lock(hashtextextended('sandbox-cashout:'||c::text,0));
  update private.sandbox_cashout_executions e set source_hold=true where e.creator_id=c and e.phase<>'canceled'
   and exists(select 1 from private.sandbox_cashout_merch_allocations a where a.execution_id=e.id and a.order_id=source_id
    and (private.sandbox_cashout_merch_source(a.order_id,e.qualification_id)->>'sourceHash') is distinct from a.source_hash);
 end loop;
 return null;
end; $function$

CREATE OR REPLACE FUNCTION private.hold_sandbox_cashout_changed_source()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare c uuid;
begin
 if tg_op='DELETE' then
  if old.environment<>'sandbox' then return null; end if;
 elsif new.environment<>'sandbox' then return null; end if;
 c:=case when tg_op='DELETE' then old.creator_id else new.creator_id end;
 if c is null then return null; end if;
 perform pg_advisory_xact_lock(hashtextextended('sandbox-cashout:'||c::text,0));
 update private.sandbox_cashout_executions e set source_hold=true
 where e.creator_id=c and e.phase<>'canceled' and exists(
  select 1 from private.sandbox_cashout_allocations a where a.execution_id=e.id
  and (private.sandbox_cashout_source(a.money_ledger_id,e.qualification_id)->>'sourceHash') is distinct from a.source_hash);
 return null;
end; $function$

CREATE OR REPLACE FUNCTION private.live_notification_read_context_pre_hint_receipts(p_notification_id uuid, p_viewer uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare n public.notifications; e public.notification_activity_events; r public.watch_party_rooms;
  source jsonb; publication jsonb; creator jsonb; state text:='live';
begin
  if p_viewer is null or public.is_account_access_restricted(p_viewer::text) then return '{}'; end if;
  select * into n from public.notifications where id=p_notification_id and user_id=p_viewer;
  if not found or n.notification_type not in ('followed_creator_live','circle_friend_live','live_room_member_joined')
    or n.source_type is distinct from 'notification_activity' then return '{}'; end if;
  select * into e from public.notification_activity_events where id=private.discovery_notification_uuid(n.source_id)
    and notification_id=n.id and recipient_user_id=p_viewer and event_kind=n.notification_type and actor_user_id=n.actor_user_id;
  if not found or e.materialized_at is null or public.is_account_access_restricted(e.actor_user_id::text)
    or public.account_deletion_public_hidden_reason(e.actor_user_id::text) is not null
    or public.has_channel_audience_block_between(e.actor_user_id::text,p_viewer::text) then return '{}'; end if;
  if n.notification_type='live_room_member_joined' then
    select * into r from public.watch_party_rooms where party_id=e.source_id;
    select jsonb_build_array(p.publication_id,p.started_at,p.retired_at) into publication
      from (select 1) singleton left join private.party_room_discovery_publications p on p.party_id=r.party_id;
    if r.party_id is null or r.notification_join_generation::text is distinct from e.context->>'generation'
      or publication is distinct from e.context->'publication' or r.host_user_id::text is distinct from e.context->>'hostId'
      or n.target_entity_id is distinct from r.party_id
      or n.target_route is distinct from (case when r.room_type='live' then '/watch-party/live-stage/[partyId]' else '/watch-party/[partyId]' end)
      or not private.live_room_join_recipient_allowed(r,e.actor_user_id,p_viewer) then return '{}'; end if;
    return jsonb_build_object('allowed',true,'liveState','live');
  end if;
  if e.context->>'sourceType' in ('live_stage','party_room') then
    select * into r from public.watch_party_rooms where party_id=e.source_id;
  elsif e.context->>'sourceType'='broadcast' then
    select room.* into r from public.room_broadcast_sessions b join public.watch_party_rooms room
      on room.party_id=coalesce(nullif(b.source_room_id,''),nullif(b.watch_party_room_id,''))
      where b.id=private.discovery_notification_uuid(e.source_id);
  else return '{}'; end if;
  if r.party_id is null or r.host_user_id is distinct from e.actor_user_id
    or r.discovery_visibility not in ('public','circle')
    or (r.discovery_visibility='circle' and not public.is_active_chilly_circle_member(r.host_user_id::text,p_viewer::text))
    or (public.is_platform_owner_user(e.actor_user_id::text)
      and not private.room_notification_owner_opt_in(r.party_id,e.actor_user_id,p_viewer))
    or (not private.social_notification_profile_allowed(e.actor_user_id::text,p_viewer)
      and not private.room_notification_owner_opt_in(r.party_id,e.actor_user_id,p_viewer))
    or public.watch_party_room_actor_blocked_by_host(r.party_id,p_viewer::text) then return '{}'; end if;
  if r.is_active then
    source:=case when e.context->>'sourceType'='party_room' then private.party_room_notification_source(e.source_id)
      else private.discovery_notification_source(e.context->>'sourceType',e.source_id) end;
    if source->>'eligible' is distinct from 'true' or source->>'revision' is distinct from e.context->>'revision'
      or source->>'audience' is distinct from e.context->>'audience'
      or source->>'target_route' is distinct from n.target_route or source->>'target_entity_id' is distinct from n.target_entity_id
      then return '{}'; end if;
    if e.context->>'sourceType'='party_room' and not private.party_room_metadata_allowed(r.party_id,p_viewer,r.discovery_visibility)
      then return '{}'; end if;
  else
    if r.discovery_visibility<>'public' or e.context->>'audience' is distinct from 'public' then return '{}'; end if;
    state:='ended';
  end if;
  creator:=case when public.is_platform_owner_user(e.actor_user_id::text)
    then jsonb_build_object('creator_display_name',private.room_discovery_host_label(r))
    else private.notification_target_display(p_viewer,'/channel/[userId]',e.actor_user_id::text) end;
  return jsonb_build_object('allowed',true,'liveState',state,'creatorId',e.actor_user_id,
    'creatorName',creator->>'creator_display_name','targetTitle',private.notification_display_label(r.discovery_title,160));
end $function$

CREATE OR REPLACE FUNCTION private.lock_sandbox_cashout_creator(p_creator uuid)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
 perform 1 from public.merch_orders where creator_id=p_creator and environment='sandbox' order by id for update;
 -- Canonical auction refunds lock their quote before appending terminal ledger rows.
 -- Lock quotes first so a started refund cannot be missed at dispatch admission.
 perform 1 from private.creator_event_auction_quotes where creator_id=p_creator and environment='test' order by id for update;
 perform 1 from private.creator_room_auction_quotes where creator_id=p_creator and environment='test' order by id for update;
 perform 1 from public.money_access_ledger_events where creator_id=p_creator and environment='sandbox' order by id for update;
 perform pg_advisory_xact_lock(hashtextextended('sandbox-cashout:'||p_creator::text,0));
end; $function$

CREATE OR REPLACE FUNCTION private.merch_reconciliation_health_snapshot()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare c private.merch_reconciliation_driver; h jsonb; t jsonb; metrics jsonb;
 alerts jsonb:='[]'; last_start timestamptz; successes bigint; failures bigint; runs bigint;
begin
 select * into strict c from private.merch_reconciliation_driver where singleton;
 h:=private.merch_reconciliation_backlog_health();
 select max(started_at),count(*) filter(where started_at>=now()-interval '6 hours'),
  coalesce(sum(completed) filter(where started_at>=now()-interval '6 hours'),0),
  coalesce(sum(incomplete) filter(where started_at>=now()-interval '6 hours'),0)
 into last_start,runs,successes,failures from private.merch_reconciliation_run_observations;
 select jsonb_build_object('assigned',count(*),
  'unqualified',count(*) filter(where not private.merch_tracking_configured(a.creator_id,o.environment)),
  'overdue12h',count(*) filter(where j.checked_at is null or j.checked_at<now()-interval '12 hours'),
  'reviewRequired',count(*) filter(where j.review_reason is not null)) into t
 from private.merch_tracking_assignments a join private.merch_tracking_jobs j on j.assignment_id=a.id
 join public.merch_orders o on o.id=a.order_id
 where a.id=private.merch_active_tracking_assignment(a.order_id);
 if not c.enabled then alerts:=alerts||'"driver_disabled"'::jsonb;
 elsif last_start is null or last_start<now()-interval '30 minutes' then alerts:=alerts||'"driver_heartbeat_missing"'::jsonb;end if;
 if (h->>'refreshOverdue12h')::bigint>0 then alerts:=alerts||'"cost_refresh_overdue"'::jsonb;end if;
 if failures>0 then alerts:=alerts||'"provider_refresh_failures"'::jsonb;end if;
 if (h->>'eligible')::bigint>0 and runs>=24 and successes<(h->>'eligible')::bigint
 then alerts:=alerts||'"observed_capacity_shortfall"'::jsonb;end if;
 if (t->>'unqualified')::bigint>0 then alerts:=alerts||'"tracking_unqualified"'::jsonb;end if;
 if (t->>'overdue12h')::bigint>0 then alerts:=alerts||'"tracking_refresh_overdue"'::jsonb;end if;
 if (t->>'reviewRequired')::bigint>0 then alerts:=alerts||'"tracking_review_required"'::jsonb;end if;
 metrics:=jsonb_build_object('windowHours',6,'runs',runs,'completed',successes,'incomplete',failures,
  'lastRunAt',last_start,'capacityGuaranteed',false);
 return jsonb_build_object('schemaVersion',1,'observedAt',now(),'environment','sandbox',
  'driverEnabled',c.enabled,'cost',h,'tracking',t,'measured',metrics,'alerts',alerts,
  'financialAuthority',false,'liveActivationAllowed',false);
end $function$

CREATE OR REPLACE FUNCTION private.notification_discovery_hint_key(p_notification uuid, p_viewer uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare e public.notification_activity_events; r public.watch_party_rooms; result uuid; source_kind text;
begin
  if p_viewer is distinct from auth.uid() or not public.discovery_reader_session_current()
    or private.live_notification_read_context(p_notification,p_viewer)->>'allowed' is distinct from 'true' then return null; end if;
  select activity.* into e from public.notification_activity_events activity join public.notifications n on n.id=p_notification
    where n.user_id=p_viewer and n.source_type='notification_activity' and n.source_id=activity.id::text
      and activity.notification_id=n.id and activity.recipient_user_id=p_viewer;
  if e.event_kind='live_room_member_joined' then
    select discovery_hint_key into result from private.room_attendance_hint_receipts
      where notification_id=p_notification and event_id=e.id and recipient_user_id=p_viewer;
    return result;
  end if;
  source_kind:=case e.context->>'sourceType' when 'party_room' then 'party_room' when 'live_stage' then 'live_stage_room'
    when 'broadcast' then 'watch_party_room' end;
  if source_kind is null then return null; end if;
  select room.* into r from public.watch_party_rooms room where room.party_id=case
    when source_kind='watch_party_room' then (select coalesce(nullif(b.source_room_id,''),nullif(b.watch_party_room_id,''))
      from public.room_broadcast_sessions b where b.id=private.discovery_notification_uuid(e.source_id)) else e.source_id end;
  if r.discovery_visibility='public' then
    select d.discovery_hint_key into result from public.discovery_feed_items d
      where d.source_type=source_kind and d.source_id=case when source_kind='watch_party_room' then r.party_id else e.source_id end;
  elsif r.discovery_visibility='circle' then
    select d.discovery_hint_key into result from public.circle_spectator_feed_items d
      where d.source_type=source_kind and d.source_id=case when source_kind='watch_party_room' then r.party_id else e.source_id end;
  end if;
  return result;
end $function$

CREATE OR REPLACE FUNCTION private.notification_moderation_target(p_report safety_reports)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_target uuid; v_owner text; v_status text; v_expected text; v_route text:='/profile/[userId]'; v_kind text;
  v_action_at timestamptz; v_action_by text; v_thread uuid;
begin
  if p_report.status<>'actioned' or p_report.resolved_at is null or p_report.resolved_by is null
    or p_report.resolution_type not in ('target_hidden','target_removed','target_restored') then return null; end if;
  v_target:=public.admin_reports_safe_uuid(p_report.target_id);
  if v_target is null then return null; end if;
  v_expected:=case p_report.resolution_type when 'target_hidden' then 'hidden' when 'target_removed' then 'removed' else 'clean' end;
  case p_report.target_type
    when 'creator_video' then
      select owner_id::text,moderation_status,moderated_at,moderated_by into v_owner,v_status,v_action_at,v_action_by from public.videos where id=v_target;
      v_route:='/channel-studio';
    when 'profile_post' then
      select user_id,moderation_status,moderated_at,moderated_by into v_owner,v_status,v_action_at,v_action_by from public.profile_posts where id=v_target and deleted_at is null;
    when 'profile_post_comment' then
      select user_id,moderation_status,moderated_at,moderated_by into v_owner,v_status,v_action_at,v_action_by from public.profile_post_comments where id=v_target and deleted_at is null;
    when 'creator_video_comment' then
      select user_id,moderation_status,moderated_at,moderated_by into v_owner,v_status,v_action_at,v_action_by from public.creator_video_comments where id=v_target and deleted_at is null;
    when 'social_attachment' then
      select owner_user_id,moderation_status,moderated_at,moderated_by into v_owner,v_status,v_action_at,v_action_by from public.social_attachments where id=v_target and deleted_at is null;
    when 'profile_media' then
      v_kind:=lower(coalesce(p_report.context->>'profileMediaKind',p_report.context->>'profile_media_kind',''));
      if v_kind not in ('avatar','background') then return null; end if;
      select user_id,case when v_kind='avatar' then profile_avatar_media_status else profile_background_media_status end,profile_media_updated_at
        into v_owner,v_status,v_action_at from public.user_profiles where user_id=v_target::text;
      v_expected:=case p_report.resolution_type when 'target_hidden' then 'flagged' when 'target_removed' then 'admin_removed' else 'active' end;
    when 'chat_message' then
      select sender_user_id,moderation_status,moderation_actioned_at,moderation_actioned_by,thread_id
        into v_owner,v_status,v_action_at,v_action_by,v_thread from public.chat_messages
        where id=v_target and moderation_report_id=p_report.id;
      if v_thread is null or v_thread::text is distinct from coalesce(p_report.context->>'threadId',p_report.context->>'thread_id')
        or not exists(select 1 from public.chat_thread_members where thread_id=v_thread and user_id=v_owner)
        then return null; end if;
      v_route:='/chat/[threadId]';
    else return null;
  end case;
  if v_owner is null or v_status is distinct from v_expected or v_action_at is distinct from p_report.resolved_at
    or (p_report.target_type<>'profile_media' and v_action_by is distinct from p_report.resolved_by::text)
    or public.admin_reports_safe_uuid(v_owner) is null
    or not exists(select 1 from auth.users where id=v_owner::uuid) then return null; end if;
  return jsonb_build_object('owner',v_owner,'route',v_route,'threadId',v_thread,'targetType',p_report.target_type,
    'targetId',v_target,'resolution',p_report.resolution_type);
end $function$

CREATE OR REPLACE FUNCTION private.notification_money_display_from_ledger(p_ledger_event_id uuid, p_recipient_user_id uuid, p_notification_type text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare l public.money_access_ledger_events; i public.money_purchase_intents; p public.monetization_products;
  buyer_kind text; seller_kind text; route text; target text; c jsonb; seller boolean;
begin
  select * into l from public.money_access_ledger_events where id=p_ledger_event_id;
  if not found or l.provider_event_id is null or l.status not in ('verified','sandbox_only','refunded','reversed','chargeback')
    or l.creator_id is null or p_recipient_user_id not in (l.user_id,l.creator_id) then return '{}'; end if;
  select * into i from public.money_purchase_intents where id::text=l.metadata->>'purchase_intent_id';
  if not found or i.user_id is distinct from l.user_id or i.creator_id is distinct from l.creator_id
    or i.product_id is distinct from l.product_id or i.source_id is distinct from l.source_id
    or i.source_type is distinct from l.source_type or i.environment is distinct from l.environment then return '{}'; end if;
  select * into p from public.monetization_products where id=l.product_id;
  if not found or p.product_type is distinct from i.product_type or p.product_key is distinct from i.product_key then return '{}'; end if;
  case i.product_type
    when 'paid_content_access' then buyer_kind:='paid_video_unlocked';seller_kind:='paid_video_sold';route:='/player/[id]';
      select id::text into target from public.videos where id=i.source_id and owner_id=i.creator_id;
    when 'channel_subscription' then buyer_kind:='channel_subscription_active';seller_kind:='channel_subscription_started';route:='/channel-subscription/[creatorId]';target:=i.creator_id::text;
    when 'vip_pass' then buyer_kind:='vip_access_active';seller_kind:='vip_pass_sold';route:='/vip-pass/[creatorId]';target:=i.creator_id::text;
    when 'creator_tip' then buyer_kind:='tip_sent_receipt';seller_kind:='tip_received';route:='/channel/[userId]';target:=i.creator_id::text;
    when 'event_pass' then
      buyer_kind:='event_pass_active';seller_kind:='event_pass_sold';route:='/event/[eventId]';
      select creator_event_id::text into target from public.paid_creator_events where creator_event_id=i.source_id and creator_id=i.creator_id;
    when 'watch_party_live_ticket' then
      buyer_kind:='watch_party_ticket_ready';seller_kind:='watch_party_ticket_sold';route:='/watch-party/[partyId]';
      select o.party_id into target from public.paid_watch_party_offers o join public.watch_party_rooms r on r.party_id=o.party_id
        where o.id=i.source_id and o.creator_id=i.creator_id and r.host_user_id=i.creator_id;
    when 'live_watch_party_access_pass' then
      buyer_kind:='live_watch_party_access_ready';seller_kind:='live_watch_party_access_sold';route:='/watch-party/live-stage/[partyId]';
      select o.party_id into target from public.paid_live_watch_party_offers o join public.watch_party_rooms r on r.party_id=o.party_id
        where o.id=i.source_id and o.creator_id=i.creator_id and o.pass_type=i.product_type and r.host_user_id=i.creator_id;
    when 'live_watch_party_seat_pass' then
      buyer_kind:='live_watch_party_seat_eligible';seller_kind:='live_watch_party_seat_sold';route:='/watch-party/live-stage/[partyId]';
      select o.party_id into target from public.paid_live_watch_party_offers o join public.watch_party_rooms r on r.party_id=o.party_id
        where o.id=i.source_id and o.creator_id=i.creator_id and o.pass_type=i.product_type and r.host_user_id=i.creator_id;
    else return '{}';
  end case;
  if target is null then return '{}'; end if;
  if route in ('/watch-party/[partyId]','/watch-party/live-stage/[partyId]')
    and nullif(i.metadata->>'party_id','') is not null and i.metadata->>'party_id'<>target then return '{}'; end if;
  seller:=p_recipient_user_id=l.creator_id and p_notification_type=seller_kind;
  if p_notification_type in ('creator_money_refunded','creator_money_revoked') then
    if (p_notification_type='creator_money_refunded' and (l.status<>'refunded' or l.event_type<>'REFUND'))
      or (p_notification_type='creator_money_revoked' and (l.status<>'reversed' or l.event_type<>'REVOCATION')) then return '{}'; end if;
    seller:=p_recipient_user_id=l.creator_id;
  elsif l.status not in ('verified','sandbox_only')
    or l.event_type not in ('INITIAL_PURCHASE','NON_RENEWING_PURCHASE','PRODUCT_CHANGE','RENEWAL','UNCANCELLATION')
    or not ((p_recipient_user_id=l.user_id and p_notification_type=buyer_kind) or seller) then return '{}'; end if;
  c:=private.notification_target_display(p_recipient_user_id,route,target);
  -- Exact source owner is also mandatory; a mismatched catalog/offer can never
  -- attach an unrelated creator's title to this receipt.
  if c->>'creator_id' is not null and c->>'creator_id'<>l.creator_id::text then return '{}'; end if;
  if c->>'creator_id' is null then
    c:=private.notification_target_display(p_recipient_user_id,'/channel/[userId]',l.creator_id::text);
  end if;
  if c->>'creator_id' is distinct from l.creator_id::text then return '{}'; end if;
  return c||jsonb_build_object('version',1,'target_id',case when seller then l.creator_id::text else target end,
    'target_route',case when seller then '/channel-studio' else route end);
end;
$function$

CREATE OR REPLACE FUNCTION private.notification_target_display(p_viewer uuid, p_route text, p_target text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare owner_id uuid; subject text; creator text; handle text; v public.videos; e public.creator_events;
  r public.watch_party_rooms; x public.creator_replay_library_items; target_uuid uuid;
begin
  if p_viewer is null or public.is_account_access_restricted(p_viewer::text) then return '{}'; end if;
  if p_target ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then target_uuid:=p_target::uuid; end if;
  if p_route in ('/vip-pass/[creatorId]','/channel-subscription/[creatorId]','/channel/[userId]','/channel-studio') then
    owner_id:=target_uuid;
  elsif p_route='/event/[eventId]' then
    select * into e from public.creator_events where id=target_uuid;
    if not found or not public.can_read_creator_event(e.id,p_viewer) then return '{}'; end if;
    owner_id:=e.host_user_id; subject:=e.event_title;
  elsif p_route='/player/[id]' then
    select * into v from public.videos where id=target_uuid;
    if not found then return '{}'; end if;
    -- The normal video predicate is deliberately session-bound. Service delivery
    -- may disclose only public-safe metadata, never impersonate a buyer session.
    if auth.role()='service_role' then
      if not coalesce(private.discovery_notification_video_public(v),false)
        or public.is_creator_video_viewer_blocked(v.owner_id::text,p_viewer::text) then return '{}'; end if;
    elsif not public.can_read_creator_video_row(v.owner_id::text,v.visibility,v.moderation_status,
      v.scan_status,v.storage_path,v.storage_object_key,v.playback_url,p_viewer::text) then return '{}'; end if;
    owner_id:=v.owner_id; subject:=v.title;
  elsif p_route='/player/replay/[replayId]' then
    select * into x from public.creator_replay_library_items where id=target_uuid;
    if not found or not public.can_read_creator_replay_library_item(x.id,p_viewer::text) then return '{}'; end if;
    owner_id:=x.owner_user_id::uuid; subject:=x.title;
  elsif p_route in ('/watch-party/[partyId]','/watch-party/live-stage/[partyId]') then
    select * into r from public.watch_party_rooms where party_id=p_target;
    if not found or not public.watch_party_room_self_access_allowed_internal(r.party_id,p_viewer::text)
      or not (r.host_user_id=p_viewer or r.discovery_visibility='public'
        or exists(select 1 from public.watch_party_room_memberships m where m.party_id=r.party_id
          and m.user_id=p_viewer::text and m.membership_state in ('active','reconnecting')
          and m.last_seen_at >= now()-interval '45 seconds')) then return '{}'; end if;
    owner_id:=r.host_user_id; subject:=r.discovery_title;
  else return '{}'; end if;
  if owner_id is null or public.is_account_access_restricted(owner_id::text)
    or not exists(select 1 from auth.users where id=owner_id)
    or public.account_deletion_public_hidden_reason(owner_id::text) is not null
    or exists(select 1 from public.channel_audience_blocks b
      where (b.channel_user_id=owner_id::text and b.blocked_user_id=p_viewer::text)
         or (b.channel_user_id=p_viewer::text and b.blocked_user_id=owner_id::text)) then return '{}'; end if;
  if auth.role()='service_role' then
    if public.is_platform_owner_user(owner_id::text) or not exists(select 1 from public.user_profiles
      where user_id=owner_id::text and profile_access_visibility='public') then return '{}'; end if;
  elsif not coalesce((public.resolve_profile_visibility_access(owner_id::text,p_viewer::text)->>'allowed')::boolean,false)
    then return '{}'; end if;
  select private.notification_display_label(p.display_name,80),private.notification_display_label(p.username,60)
    into creator,handle from public.user_profiles p where p.user_id=owner_id::text;
  if creator is null then creator:=case when handle is not null then '@'||handle end;
  elsif handle is not null and lower(creator) not in (lower(handle),lower('@'||handle))
    then creator:=creator||' (@'||handle||')'; end if;
  return jsonb_build_object('creator_id',owner_id,'creator_display_name',creator,
    'subject_title',private.notification_display_label(subject,160),'target_id',p_target);
end;
$function$

CREATE OR REPLACE FUNCTION private.party_room_notification_source(p_party_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare r public.watch_party_rooms; p private.party_room_discovery_publications; projection uuid;
begin
  if not private.party_room_publication_current(p_party_id) then return '{"eligible":false}'; end if;
  select * into r from public.watch_party_rooms where party_id=p_party_id;
  select * into p from private.party_room_discovery_publications where party_id=p_party_id;
  if r.discovery_visibility='public' then
    select id into projection from public.discovery_feed_items where source_type='party_room' and source_id=p_party_id
      and is_publicly_discoverable and live_state='live' and ended_at is null
      and metadata->>'publication_id'=p.publication_id::text and metadata->>'canonical_projection_active'='true';
  else
    select id into projection from public.circle_spectator_feed_items where source_type='party_room' and source_id=p_party_id
      and status='active' and live_state='live' and ended_at is null
      and metadata->>'publication_id'=p.publication_id::text and metadata->>'canonical_projection_active'='true';
  end if;
  if projection is null then return '{"eligible":false}'; end if;
  return jsonb_build_object('eligible',true,'owner',r.host_user_id,'audience',r.discovery_visibility,
    'revision',p.publication_id,'target_route','/spectate/[itemId]','target_entity_id',projection,
    'title','Watch-Party Live started');
end $function$

CREATE OR REPLACE FUNCTION private.qualify_live_notification_view()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_owner uuid; v_authority jsonb; v_session uuid;
begin
  -- Only a viewer's current authenticated heartbeat qualifies; host actions,
  -- removed/reconnecting rows and mere initial membership do not count.
  if not public.whole_app_exact_current_session_authority_internal()
    or auth.uid()::text<>new.user_id or new.membership_state<>'active'
    or old.membership_state<>'active' or new.left_at is not null or old.left_at is not null
    or new.joined_at>now()-interval '10 seconds' or old.last_seen_at<now()-interval '45 seconds'
    or new.last_seen_at is not distinct from old.last_seen_at
    or new.last_seen_at<now()-interval '5 seconds' or new.last_seen_at>now()+interval '1 second'
    then return new; end if;
  select host_user_id into v_owner from public.watch_party_rooms where party_id=new.party_id and room_type='live' and is_active;
  if not found or v_owner=auth.uid() then return new; end if;
  v_session:=nullif(auth.jwt()->>'session_id','')::uuid;
  if v_session is null then return new; end if;
  v_authority:=public.resolve_watch_party_livekit_viewer_authority(new.party_id,auth.uid(),v_session);
  if coalesce((v_authority->>'allowed')::boolean,false) then
    perform private.record_qualified_notification_view('live',new.party_id,v_owner,auth.uid());
  end if;
  return new;
end $function$

CREATE OR REPLACE FUNCTION private.record_qualified_notification_view(p_kind text, p_source_id text, p_creator uuid, p_viewer uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_day date:=(now() at time zone 'UTC')::date; v_due timestamptz;
begin
  if p_creator is null or p_viewer is null or p_creator=p_viewer
    or public.is_account_access_restricted(p_creator::text) or public.is_account_access_restricted(p_viewer::text)
    or public.has_channel_audience_block_between(p_creator::text,p_viewer::text) then return false; end if;
  insert into public.notification_qualified_views(creator_user_id,viewer_user_id,view_kind,source_id,view_day)
    values(p_creator,p_viewer,p_kind,p_source_id,v_day) on conflict do nothing;
  if not found then return true; end if;
  v_due:=((v_day+1)::timestamp at time zone 'UTC');
  perform private.enqueue_notification_activity('view-summary:'||p_creator::text||':'||p_kind||':'||v_day::text,
    p_kind||'_view_summary',v_day::text,null,p_creator,jsonb_build_object('viewDay',v_day,'viewKind',p_kind),
    v_due,v_due+interval '2 days');
  return true;
end $function$

CREATE OR REPLACE FUNCTION private.refresh_merch_reconciliation_alerts()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare h jsonb; s private.merch_reconciliation_alert_state; fp text; owner_id uuid;
event_id uuid; ev public.notification_activity_events; plan jsonb; v_notification_id uuid;
 emitted integer:=0;
begin
 select * into strict s from private.merch_reconciliation_alert_state where singleton for update;
 h:=private.merch_reconciliation_health_snapshot();
 fp:=md5((h->'alerts')::text);
 if s.fingerprint is distinct from fp then
  update private.merch_reconciliation_alert_state set fingerprint=fp,episode=extensions.gen_random_uuid(),
   alerts=h->'alerts',health=h,last_checked_at=clock_timestamp(),has_warned=has_warned or h->'alerts'<>'[]'::jsonb where singleton returning * into s;
 else
  update private.merch_reconciliation_alert_state set health=h,last_checked_at=clock_timestamp()
   where singleton returning * into s;
 end if;
 if not s.has_warned then return jsonb_build_object('emitted',0,'financialAuthority',false); end if;
 -- A stable incident is deduplicated per current verified owner. New owners
 -- receive the still-active incident; removed owners lose delivery eligibility.
 for owner_id in select distinct membership.user_id::uuid from public.platform_role_memberships membership
  where membership.role='owner' and membership.status='active'
   and public.platform_subject_has_role_internal(membership.user_id,array['owner']) loop
  event_id:=private.enqueue_notification_activity(
   'owner-reconciliation:'||s.episode::text||':'||owner_id::text,'owner_reconciliation_health',s.episode::text,
   null,owner_id,jsonb_build_object('episode',s.episode),clock_timestamp(),clock_timestamp()+interval '7 days');
  if event_id is not null then
   select * into strict ev from public.notification_activity_events where id=event_id for update;
   plan:=private.resolve_notification_activity(ev);
   v_notification_id:=null;
   if coalesce((plan->>'eligible')::boolean,false) and coalesce((plan->>'in_app_allowed')::boolean,false) then
    insert into public.notifications(user_id,actor_user_id,category,notification_type,title,body,
     target_route,target_entity_id,target_context,deep_link,source_type,source_id,status,delivered_at)
    values(owner_id,null,plan->>'category',plan->>'notification_type',plan->>'title',plan->>'body',
     plan->>'target_route',plan->>'target_entity_id',coalesce(plan->'target_context','{}'),plan->>'deep_link',
     'notification_activity',event_id::text,'sent',clock_timestamp()) returning id into v_notification_id;
   end if;
   -- In-app delivery is committed now even if the push worker is unavailable.
   -- Its existing producer rechecks role/preferences and owns push receipts.
   update public.notification_activity_events set materialized_at=clock_timestamp(),notification_id=v_notification_id
    where id=event_id;
   emitted:=emitted+1;
  end if;
 end loop;
 return jsonb_build_object('emitted',emitted,'episode',s.episode,'financialAuthority',false);
end $function$

CREATE OR REPLACE FUNCTION private.resolve_account_notification_activity(p_event notification_activity_events)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare s private.merch_reconciliation_alert_state; recovered boolean;
begin
 if p_event.event_kind<>'owner_reconciliation_health' then
  return private.resolve_account_notification_before_reconciliation(p_event); end if;
 select * into s from private.merch_reconciliation_alert_state where singleton;
 if not public.platform_subject_has_role_internal(p_event.recipient_user_id::text,array['owner'])
  or p_event.actor_user_id is not null or p_event.source_id is distinct from s.episode::text
  or p_event.context->>'episode' is distinct from s.episode::text
 then return '{"eligible":false}'::jsonb; end if;
 recovered:=s.alerts='[]'::jsonb;
 return jsonb_build_object('eligible',true,'preference_key','account_activity_enabled',
  'category','moderation_notice','notification_type','payout_readiness_updated',
  'title',case when recovered then 'Chi''llywood operations: checks recovered' else 'Chi''llywood operations need attention' end,
  'body',case when recovered then 'The monitored shipment and cost-refresh warnings cleared. This does not enable payments or payouts.'
    else 'Open Owner Money Center to review shipment verification, provider refresh and queue health. Payments and payouts are not enabled by this alert.' end,
  'target_route','/admin','target_entity_id',s.episode::text,
  'target_context',jsonb_build_object('section','money','alertCodes',s.alerts,'observedAt',s.last_checked_at),
  'push_allowed',true);
end $function$

CREATE OR REPLACE FUNCTION private.resolve_account_notification_before_reconciliation(p_event notification_activity_events)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_report public.safety_reports; v_target jsonb;
begin
  if p_event.event_kind<>'moderation_notice' or p_event.actor_user_id is not null or p_event.source_id !~ '^[0-9]{1,18}$'
    then return '{"eligible":false}'; end if;
  select * into v_report from public.safety_reports where id=p_event.source_id::bigint;
  if not found or v_report.resolution_type is distinct from p_event.context->>'resolution'
    or to_jsonb(v_report.resolved_at) is distinct from p_event.context->'resolvedAt' then return '{"eligible":false}'; end if;
  v_target:=private.notification_moderation_target(v_report);
  if v_target is null or v_target->>'owner' is distinct from p_event.recipient_user_id::text then return '{"eligible":false}'; end if;
  return jsonb_build_object('eligible',true,'category','moderation_notice','notification_type','moderation_notice',
    'title','Content moderation update','body',case v_report.resolution_type
      when 'target_hidden' then 'Your content was hidden after review.'
      when 'target_removed' then 'Your content was removed after review.'
      else 'Your content was restored after review.' end,
    'target_route',v_target->>'route','target_entity_id',case when v_target->>'route'='/profile/[userId]' then p_event.recipient_user_id::text
      when v_target->>'route'='/chat/[threadId]' then v_target->>'threadId' else null end,
    'target_context',jsonb_build_object('resolution',v_report.resolution_type),
    'preference_key','account_activity_enabled');
end $function$

CREATE OR REPLACE FUNCTION private.resolve_discovery_notification_activity(e notification_activity_events)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare result jsonb;b private.room_start_notification_bindings;
begin
  result:=private.resolve_discovery_notification_pre_room_start_binding(e);
  if result->>'eligible'='true' and e.event_kind in ('followed_creator_live','circle_friend_live') then
    b:=private.current_room_start_notification_binding(e);
    if b.event_id is null then return '{"eligible":false}'; end if;
  end if;
  return result;
end $function$

CREATE OR REPLACE FUNCTION private.resolve_discovery_notification_before_subject_context(p_event notification_activity_events)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare s jsonb; friend boolean;
begin
  if p_event.context->>'sourceType' is distinct from 'party_room' then
    return private.resolve_discovery_notification_pre_party_room(p_event); end if;
  if p_event.event_kind not in ('circle_friend_live','followed_creator_live') then return '{"eligible":false}'; end if;
  s:=private.party_room_notification_source(p_event.source_id);
  if s->>'eligible' is distinct from 'true' or s->>'owner' is distinct from p_event.actor_user_id::text
    or s->>'revision' is distinct from p_event.context->>'revision' or s->>'audience' is distinct from p_event.context->>'audience'
    or not private.party_room_metadata_allowed(p_event.source_id,p_event.recipient_user_id,s->>'audience')
    then return '{"eligible":false}'; end if;
  friend:=public.is_active_chilly_circle_member(p_event.actor_user_id::text,p_event.recipient_user_id::text);
  if (p_event.event_kind='circle_friend_live' and not friend)
    or (p_event.event_kind='followed_creator_live' and (friend or s->>'audience'<>'public' or not exists(
      select 1 from public.channel_followers where channel_user_id=p_event.actor_user_id::text and follower_user_id=p_event.recipient_user_id::text)))
    then return '{"eligible":false}'; end if;
  return jsonb_build_object('eligible',true,'category','creator_went_live','notification_type',p_event.event_kind,
    'title',s->>'title','body',case when friend then 'Someone in your Chi''lly Circle started a Watch-Party Live.'
      else 'A creator you follow started a Watch-Party Live.' end,
    'target_route',s->>'target_route','target_entity_id',s->>'target_entity_id','target_context','{}'::jsonb,
    'preference_key',case when friend then 'circle_friend_live_enabled' else 'followed_creator_live_enabled' end);
end $function$

CREATE OR REPLACE FUNCTION private.resolve_discovery_notification_pre_party_room(p_event notification_activity_events)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare s jsonb; e public.creator_events; reminder public.event_reminders;
  kind text:=p_event.event_kind; category text; preference text; body_text text;
begin
  if kind in ('followed_creator_live','circle_friend_live','public_upload','replay_later') then
    s:=private.discovery_notification_source(p_event.context->>'sourceType',p_event.source_id);
    if not coalesce((s->>'eligible')::boolean,false)
      or s->>'owner' is distinct from p_event.actor_user_id::text
      or s->>'revision' is distinct from p_event.context->>'revision'
      or s->>'audience' is distinct from p_event.context->>'audience'
    then return '{"eligible":false}'; end if;
    if kind='circle_friend_live' or (kind='replay_later' and s->>'audience'='circle') then
      if not public.is_active_chilly_circle_member(p_event.actor_user_id::text,p_event.recipient_user_id::text)
        then return '{"eligible":false}'; end if;
    elsif s->>'audience'<>'public' or not exists(select 1 from public.channel_followers f
      where f.channel_user_id=p_event.actor_user_id::text and f.follower_user_id=p_event.recipient_user_id::text)
    then return '{"eligible":false}'; end if;
    if (kind in ('followed_creator_live','circle_friend_live') and p_event.context->>'sourceType' not in ('live_stage','broadcast'))
      or (kind='public_upload' and p_event.context->>'sourceType'<>'video')
      or (kind='replay_later' and p_event.context->>'sourceType'<>'replay') then return '{"eligible":false}'; end if;
    category:=case when kind in ('public_upload','replay_later') then 'content_dropped' else 'creator_went_live' end;
    preference:=case kind when 'followed_creator_live' then 'followed_creator_live_enabled'
      when 'circle_friend_live' then 'circle_friend_live_enabled'
      when 'public_upload' then 'public_upload_enabled' else 'replay_later_enabled' end;
    body_text:=case kind when 'public_upload' then 'A creator you follow posted a public video.'
      when 'replay_later' then 'A replay is ready. Open it to check playback availability.'
      when 'circle_friend_live' then 'Someone in your Chi''lly Circle is live.' else 'A creator you follow is live.' end;
  elsif kind in ('event_starts_soon','watch_party_starts_soon','creator_event_updated','creator_event_canceled') then
    select * into e from public.creator_events where id=private.discovery_notification_uuid(p_event.source_id);
    if not found or e.host_user_id is distinct from p_event.actor_user_id
      or private.discovery_notification_event_revision(e) is distinct from p_event.context->>'revision'
      or not private.discovery_notification_event_visible(e,p_event.recipient_user_id)
    then return '{"eligible":false}'; end if;
    select * into reminder from public.event_reminders where event_id=e.id and user_id=p_event.recipient_user_id;
    if not found or reminder.status<>'active'
      or reminder.id::text is distinct from p_event.context->>'reminderId'
      or reminder.updated_at::text is distinct from p_event.context->>'reminderRevision'
    then return '{"eligible":false}'; end if;
    if kind in ('event_starts_soon','watch_party_starts_soon') then
      if e.status<>'scheduled' or not e.reminder_ready or e.starts_at is null
        or e.starts_at<=now() or e.starts_at>now()+interval '15 minutes'
      then return '{"eligible":false}'; end if;
      category:='upcoming_event_reminder'; preference:='event_starts_soon_enabled';
      body_text:='An event you saved starts soon.';
    elsif kind='creator_event_canceled' then
      if e.status<>'canceled' then return '{"eligible":false}'; end if;
      category:='social_activity'; preference:='event_updates_enabled'; body_text:='An event you saved was canceled.';
    else
      if e.status not in ('scheduled','live_now') then return '{"eligible":false}'; end if;
      category:='social_activity'; preference:='event_updates_enabled'; body_text:='An event you saved has changed.';
    end if;
    s:=jsonb_build_object('target_route','/event/[eventId]','target_entity_id',e.id::text,
      'title',case kind when 'creator_event_canceled' then 'Event canceled'
        when 'creator_event_updated' then 'Event updated' else 'Event starts soon' end);
  else return '{"eligible":false}'; end if;
  return jsonb_build_object('eligible',true,'category',category,'notification_type',kind,
    'title',s->>'title','body',body_text,'target_route',s->>'target_route',
    'target_entity_id',s->>'target_entity_id','target_context','{}'::jsonb,'preference_key',preference);
end $function$

CREATE OR REPLACE FUNCTION private.resolve_discovery_notification_pre_person_preferences(p_event notification_activity_events)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare plan jsonb; creator_name text; handle text; subject_title text; v_source_type text;
 label text; title_text text; body_text text;
begin
 plan:=private.resolve_discovery_notification_before_subject_context(p_event);
 if plan->>'eligible' is distinct from 'true' then return plan; end if;
 -- Never source an identity from caller context or JWT metadata. A deleted or
 -- restricted actor cannot expose an old profile label through this helper.
 if p_event.actor_user_id is null or not exists(select 1 from auth.users where id=p_event.actor_user_id)
   or public.is_account_access_restricted(p_event.actor_user_id::text)
   or exists(select 1 from public.account_deletion_requests where user_id::text=p_event.actor_user_id::text
      and status in ('scheduled','completed')) then return '{"eligible":false}'; end if;
 -- Profile visibility's public RPC binds auth.uid(), not an arbitrary worker
 -- recipient. Do not let an operator worker disclose a private profile name.
 select private.notification_subject_label(display_name,80),private.notification_subject_label(username,60)
   into creator_name,handle from public.user_profiles where user_id=p_event.actor_user_id::text
     and profile_access_visibility='public' and not public.is_platform_owner_user(user_id);
 if creator_name is null then creator_name:=case when handle is not null then '@'||handle else 'Creator unavailable' end;
 elsif handle is not null and lower(creator_name)<>lower(handle) and lower(creator_name)<>lower('@'||handle)
   then creator_name:=creator_name||' (@'||handle||')'; end if;
 v_source_type:=p_event.context->>'sourceType';
 if p_event.event_kind in ('event_starts_soon','watch_party_starts_soon','creator_event_updated','creator_event_canceled') then
   select private.notification_subject_label(event_title,160) into subject_title from public.creator_events
     where id=private.discovery_notification_uuid(p_event.source_id) and host_user_id=p_event.actor_user_id;
   v_source_type:='event';
 elsif v_source_type='video' then
   select private.notification_subject_label(title,160) into subject_title from public.videos
     where id=private.discovery_notification_uuid(p_event.source_id) and owner_id=p_event.actor_user_id;
 elsif v_source_type='replay' then
   select private.notification_subject_label(title,160) into subject_title from public.creator_replay_library_items
     where id=private.discovery_notification_uuid(p_event.source_id) and owner_user_id=p_event.actor_user_id::text;
 elsif v_source_type in ('live_stage','party_room') then
   select private.notification_subject_label(coalesce(nullif(btrim(r.discovery_title),''),
       case when v_source_type='party_room' then private.party_room_content_metadata(r)->>'title' end),160)
     into subject_title from public.watch_party_rooms r where party_id=p_event.source_id and host_user_id=p_event.actor_user_id;
 elsif v_source_type='broadcast' then
   select private.notification_subject_label(r.discovery_title,160) into subject_title
     from public.room_broadcast_sessions b join public.watch_party_rooms r
       on r.party_id=coalesce(nullif(b.source_room_id,''),nullif(b.watch_party_room_id,''))
     where b.id=private.discovery_notification_uuid(p_event.source_id) and r.host_user_id=p_event.actor_user_id;
 end if;
 label:=coalesce(subject_title,case v_source_type when 'video' then 'Untitled video' when 'replay' then 'Untitled replay'
   when 'event' then 'Untitled event' when 'live_stage' then 'Live Stage' else 'Watch-Party Live' end);
 if p_event.event_kind='public_upload' then
   title_text:=creator_name||' posted a video'; body_text:=label;
 elsif p_event.event_kind='replay_later' then
   title_text:=creator_name||' · Replay ready'; body_text:=label||'. Open to check playback availability.';
 elsif p_event.event_kind='creator_event_canceled' then
   title_text:='Event canceled · '||creator_name; body_text:=label||' was canceled.';
 elsif p_event.event_kind='creator_event_updated' then
   title_text:='Event updated · '||creator_name; body_text:=label||' has changed. Open for the latest details.';
 elsif p_event.event_kind in ('event_starts_soon','watch_party_starts_soon') then
   title_text:='Starting soon · '||creator_name; body_text:=label||' starts soon.';
 else
   title_text:=creator_name||' is live'; body_text:=label||'. Open to check access.';
 end if;
 return plan||jsonb_build_object('title',title_text,'body',body_text,'target_context',
   coalesce(plan->'target_context','{}'::jsonb)||jsonb_build_object('display_context',jsonb_build_object('version',1,
     'creator_id',p_event.actor_user_id,'creator_display_name',creator_name,
     'target_id',plan->>'target_entity_id','subject_title',label)));
end $function$

CREATE OR REPLACE FUNCTION private.resolve_discovery_notification_pre_room_owner_consent(p_event notification_activity_events)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare preference boolean;
begin
  if p_event.event_kind in ('followed_creator_live','circle_friend_live') then
    select case when p_event.context->>'sourceType' in ('party_room','broadcast') then watch_party_starts_enabled else live_starts_enabled end
      into preference from public.person_notification_preferences where user_id=p_event.recipient_user_id and actor_user_id=p_event.actor_user_id;
    if preference is false then return '{"eligible":false}'; end if;
  end if;
  -- ON never creates Follow/Circle membership or bypasses global preferences.
  return private.resolve_discovery_notification_pre_person_preferences(p_event);
end $function$

CREATE OR REPLACE FUNCTION private.resolve_discovery_notification_pre_room_start_binding(p_event notification_activity_events)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare plan jsonb; r public.watch_party_rooms; label text;
begin
  plan:=private.resolve_discovery_notification_pre_room_owner_consent(p_event);
  if plan->>'eligible' is distinct from 'true' or p_event.event_kind not in ('followed_creator_live','circle_friend_live')
    or not public.is_platform_owner_user(p_event.actor_user_id::text) then return plan; end if;
  if p_event.context->>'sourceType' in ('live_stage','party_room') then
    select * into r from public.watch_party_rooms where party_id=p_event.source_id;
  elsif p_event.context->>'sourceType'='broadcast' then
    select room.* into r from public.room_broadcast_sessions b join public.watch_party_rooms room
      on room.party_id=coalesce(nullif(b.source_room_id,''),nullif(b.watch_party_room_id,''))
      where b.id=private.discovery_notification_uuid(p_event.source_id);
  end if;
  if r.party_id is null or not private.room_notification_owner_opt_in(r.party_id,p_event.actor_user_id,p_event.recipient_user_id)
    then return '{"eligible":false}'; end if;
  label:=private.room_discovery_host_label(r);
  return jsonb_set(plan||jsonb_build_object('title',label||' is live'),
    '{target_context,display_context,creator_display_name}',to_jsonb(label),true);
end $function$

CREATE OR REPLACE FUNCTION private.resolve_notification_activity(p_event notification_activity_events)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_plan jsonb; v_preferences jsonb; v_route text; v_entity text;
begin
  if (p_event.expires_at is not null and p_event.expires_at<=now())
    or public.is_account_access_restricted(p_event.recipient_user_id::text)
    or (p_event.actor_user_id is not null and public.is_account_access_restricted(p_event.actor_user_id::text))
    or exists (select 1 from public.account_deletion_requests d
      where d.user_id::text in (p_event.recipient_user_id::text,p_event.actor_user_id::text) and d.status in ('scheduled','completed'))
    or exists (select 1 from public.channel_audience_blocks b
      where (b.channel_user_id=p_event.actor_user_id::text and b.blocked_user_id=p_event.recipient_user_id::text)
         or (b.channel_user_id=p_event.recipient_user_id::text and b.blocked_user_id=p_event.actor_user_id::text))
  then return '{"eligible":false}'::jsonb; end if;
  v_plan := private.resolve_social_notification_activity(p_event);
  if coalesce((v_plan->>'eligible')::boolean,false) is false then v_plan:=private.resolve_discovery_notification_activity(p_event); end if;
  if coalesce((v_plan->>'eligible')::boolean,false) is false then v_plan:=private.resolve_view_notification_activity(p_event); end if;
  if coalesce((v_plan->>'eligible')::boolean,false) is false then v_plan:=private.resolve_account_notification_activity(p_event); end if;
  if coalesce((v_plan->>'eligible')::boolean,false) is false then v_plan:=private.resolve_seat_notification_activity(p_event); end if;
  if coalesce((v_plan->>'eligible')::boolean,false) is false then return '{"eligible":false}'::jsonb; end if;
  select to_jsonb(p) into v_preferences from public.notification_preferences p where p.user_id=p_event.recipient_user_id;
  if v_plan->>'preference_key' not in ('social_activity_enabled','circle_activity_enabled','messages_enabled',
    'view_summary_enabled','event_updates_enabled','seat_activity_enabled','account_activity_enabled',
    'followed_creator_live_enabled','circle_friend_live_enabled','event_starts_soon_enabled','public_upload_enabled','replay_later_enabled')
    or nullif(v_plan->>'preference_key','') is null
    or coalesce((v_preferences->>(v_plan->>'preference_key'))::boolean,true) is false
  then return '{"eligible":false}'::jsonb; end if;
  v_route:=v_plan->>'target_route'; v_entity:=v_plan->>'target_entity_id';
  if v_route in ('/profile/[userId]','/channel/[userId]','/player/[id]','/title/[id]',
    '/chat/[threadId]','/event/[eventId]','/watch-party/[partyId]','/watch-party/live-stage/[partyId]','/spectate/[itemId]',
    '/player/replay/[replayId]')
    and v_entity ~ '^[a-zA-Z0-9_-]{1,128}$'
  then v_route:=regexp_replace(v_route,'\[[a-zA-Z]+\]',v_entity);
  elsif v_route not in ('/chilly-circle','/channel-settings','/channel-studio','/settings','/chat','/watch-party','/admin')
    or v_route is null then return '{"eligible":false}'::jsonb;
  end if;
  return v_plan || jsonb_build_object('deep_link',case when p_event.event_kind='owner_reconciliation_health'
    and v_route='/admin' then '/admin?tab=money-center&section=overview' else v_route end,
    'in_app_allowed',coalesce((v_preferences->>'in_app_enabled')::boolean,true),
    'push_allowed',coalesce((v_preferences->>'push_enabled')::boolean,true)
      and (p_event.event_kind not in ('video_view_summary','live_view_summary')
        or coalesce((v_preferences->>'view_summary_push_enabled')::boolean,false)));
end $function$

CREATE OR REPLACE FUNCTION private.resolve_seat_notification_activity(p_event notification_activity_events)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare plan jsonb; owner_id uuid; creator_name text; handle text; subject_label text;
begin
 plan:=private.resolve_seat_notification_before_subject_context(p_event);
 if plan->>'eligible' is distinct from 'true' then return plan; end if;
 if plan->>'target_route'='/event/[eventId]' then
   select e.host_user_id,case when e.visibility='public' or e.host_user_id=p_event.recipient_user_id
     then private.notification_subject_label(e.event_title,160) end into owner_id,subject_label
   from public.creator_events e where e.id=private.seat_notification_uuid(plan->>'target_entity_id');
 else
   select r.host_user_id,case when r.discovery_visibility='public' or r.host_user_id=p_event.recipient_user_id
     then private.notification_subject_label(r.discovery_title,160) end into owner_id,subject_label
   from public.watch_party_rooms r where r.party_id=plan->>'target_entity_id';
 end if;
 if owner_id is null or public.is_account_access_restricted(owner_id::text)
   or not exists(select 1 from auth.users where id=owner_id)
   or public.has_channel_audience_block_between(owner_id::text,p_event.recipient_user_id::text)
   or exists(select 1 from public.account_deletion_requests where user_id::text=owner_id::text
    and status in ('scheduled','completed')) then return '{"eligible":false}'; end if;
 select private.notification_subject_label(display_name,80),private.notification_subject_label(username,60)
 into creator_name,handle from public.user_profiles where user_id=owner_id::text
   and profile_access_visibility='public' and not public.is_platform_owner_user(user_id);
 if creator_name is null then creator_name:=case when handle is not null then '@'||handle else 'Creator unavailable' end;
 elsif handle is not null and lower(creator_name)<>lower(handle) and lower(creator_name)<>lower('@'||handle)
   then creator_name:=creator_name||' (@'||handle||')'; end if;
 subject_label:=coalesce(subject_label,case plan->>'target_route' when '/event/[eventId]' then 'Event'
   when '/watch-party/live-stage/[partyId]' then 'Live Stage' else 'Watch-Party Live' end);
 return plan||jsonb_build_object('body',creator_name||' · '||subject_label||'. '||(plan->>'body'),
   'target_context',coalesce(plan->'target_context','{}'::jsonb)||jsonb_build_object('display_context',
    jsonb_build_object('version',1,'creator_id',owner_id,'creator_display_name',creator_name,
     'target_id',plan->>'target_entity_id','subject_title',subject_label)));
end $function$

CREATE OR REPLACE FUNCTION private.resolve_seat_notification_before_subject_context(p_event notification_activity_events)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare a jsonb; buyer uuid; current_buyer uuid; route text; entity text; kind text:=p_event.event_kind;
begin
  if kind not in ('auction_outbid','auction_won','auction_creator_award','auction_checkout_deadline','auction_payment_deadline') then
    return private.resolve_seat_notification_activity_before_auctions(p_event);
  end if;
  if p_event.context->>'family'='event' then
    select to_jsonb(x) into a from private.creator_event_auctions x where x.id=private.seat_notification_uuid(p_event.source_id)
      and private.creator_event_auction_source_valid(x);
    route:='/event/[eventId]'; entity:=a->>'event_id';
    if kind='auction_outbid' then
      select buyer_id into buyer from private.creator_event_auction_bids where id=private.seat_notification_uuid(p_event.context->>'priorBidId') and auction_id=private.seat_notification_uuid(p_event.source_id);
      select buyer_id into current_buyer from private.creator_event_auction_bids where id=private.seat_notification_uuid(a->>'highest_bid_id');
    end if;
  elsif p_event.context->>'family'='room' then
    select to_jsonb(x) into a from private.creator_room_seat_auctions x where x.id=private.seat_notification_uuid(p_event.source_id)
      and private.creator_room_seat_auction_source_valid(x);
    route:=case a->>'source_kind' when 'stage_reserved_seat' then '/watch-party/live-stage/[partyId]' else '/watch-party/[partyId]' end;
    entity:=a->>'party_id';
    if not exists(select 1 from private.creator_room_sessions s where s.id=private.seat_notification_uuid(a->>'room_session_id') and s.ended_at is null)
      then return '{"eligible":false}'; end if;
    if kind='auction_outbid' then
      select buyer_id into buyer from private.creator_room_seat_auction_bids where id=private.seat_notification_uuid(p_event.context->>'priorBidId') and auction_id=private.seat_notification_uuid(p_event.source_id);
      select buyer_id into current_buyer from private.creator_room_seat_auction_bids where id=private.seat_notification_uuid(a->>'highest_bid_id');
    end if;
  else return '{"eligible":false}'; end if;
  if a is null then return '{"eligible":false}'; end if;
  if kind='auction_creator_award' then
    if p_event.recipient_user_id::text is distinct from a->>'creator_id' or p_event.actor_user_id is not null
      or a->>'state' not in('awarded','payment_pending') then return '{"eligible":false}'; end if;
  else
    if p_event.actor_user_id::text is distinct from a->>'creator_id' then return '{"eligible":false}'; end if;
    if kind='auction_outbid' then
      if buyer is distinct from p_event.recipient_user_id or current_buyer is null or current_buyer=buyer
        or a->>'state'<>'open' or (a->>'closes_at')::timestamptz<=now() then return '{"eligible":false}'; end if;
    elsif p_event.recipient_user_id::text is distinct from a->>'winner_id' or a->>'state' not in('awarded','payment_pending')
      or (a->>'payment_deadline')::timestamptz<=now() then return '{"eligible":false}';
    elsif kind='auction_checkout_deadline' and a->>'state'<>'awarded' then return '{"eligible":false}';
    end if;
  end if;
  return jsonb_build_object('eligible',true,'category',case when kind='auction_creator_award' then 'creator_money_sale' else 'creator_money_purchase' end,
    'notification_type',kind,'preference_key',case when p_event.context->>'family'='room' then 'seat_activity_enabled' else 'event_updates_enabled' end,
    'title',case kind when 'auction_outbid' then 'Your bid was outbid' when 'auction_won' then 'You won the auction'
      when 'auction_creator_award' then 'Auction awarded: payment pending' when 'auction_checkout_deadline' then 'Auction checkout deadline approaching' else 'Auction payment deadline approaching' end,
    'body',case kind when 'auction_outbid' then 'Open the auction to review its current price and closing time. No payment was taken for bidding.'
      when 'auction_won' then 'Review your winning amount and payment deadline. Winning alone does not grant admission.'
      when 'auction_creator_award' then 'A winner was selected. Payment and access still require verification.'
      when 'auction_checkout_deadline' then 'Open the auction before its checkout-start deadline if you want to complete your winning purchase.'
      else 'Check your existing checkout and payment status. Do not start a second payment.' end,
    'target_route',route,'target_entity_id',entity,'target_context',jsonb_build_object('auctionId',p_event.source_id,
      'action_expires_at',p_event.expires_at));
end $function$

CREATE OR REPLACE FUNCTION private.resolve_social_notification_activity(p_event notification_activity_events)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare r public.watch_party_rooms; m public.watch_party_room_memberships; name text; handle text; publication jsonb; generation_start timestamptz; snapshot record;
  room_title text; actor_session uuid; authority jsonb;
begin
  if p_event.event_kind<>'live_room_member_joined' then
    return private.resolve_social_notification_pre_live_room_join(p_event); end if;
  select room as room_row,jsonb_build_array(p.publication_id,p.started_at,p.retired_at) as publication,greatest(room.notification_join_started_at,p.started_at) as generation_start
    into snapshot from public.watch_party_rooms room
    left join private.party_room_discovery_publications p on p.party_id=room.party_id where room.party_id=p_event.source_id;
  if not found then return '{"eligible":false}'; end if;
  r:=snapshot.room_row; publication:=snapshot.publication; generation_start:=snapshot.generation_start;
  if not r.is_active or r.host_user_id::text is distinct from p_event.context->>'hostId'
    or r.notification_join_generation::text is distinct from p_event.context->>'generation'
    or publication is distinct from p_event.context->'publication'
    or not private.live_room_join_recipient_allowed(r,p_event.actor_user_id,p_event.recipient_user_id)
    then return '{"eligible":false}'; end if;
  select * into m from public.watch_party_room_memberships where party_id=r.party_id and user_id=p_event.actor_user_id::text;
  if not found or m.membership_state<>'active' or m.left_at is not null
    or m.joined_at::text is distinct from p_event.context->>'joinedAt' or m.joined_at<generation_start
    or m.last_seen_at<now()-interval '45 seconds' then return '{"eligible":false}'; end if;
  actor_session:=private.discovery_notification_uuid(p_event.context->>'actorSession');
  if actor_session is null or not exists(select 1 from auth.sessions s where s.id=actor_session
    and s.user_id=p_event.actor_user_id and (s.not_after is null or s.not_after>now())) then return '{"eligible":false}'; end if;
  authority:=public.resolve_watch_party_livekit_viewer_authority(r.party_id,p_event.actor_user_id,actor_session);
  if authority->>'allowed' is distinct from 'true' then return '{"eligible":false}'; end if;
  if private.social_notification_profile_allowed(p_event.actor_user_id::text,p_event.recipient_user_id) then
    select private.notification_subject_label(display_name,80),private.notification_subject_label(username,60)
      into name,handle from public.user_profiles where user_id=p_event.actor_user_id::text;
    if name is null then name:=case when handle is not null then '@'||handle end;
    elsif handle is not null and lower(name) not in(lower(handle),lower('@'||handle)) then name:=name||' (@'||handle||')'; end if;
  elsif p_event.recipient_user_id=r.host_user_id then
    -- Host already has authorized roster access, not private profile access.
    name:=private.notification_subject_label(m.display_name,80);
  end if;
  if name is null then return '{"eligible":false}'; end if;
  room_title:=coalesce(private.notification_subject_label(r.discovery_title,160),
    case when r.room_type='title' then private.notification_subject_label(private.party_room_content_metadata(r)->>'title',160) end,
    case when r.room_type='live' then 'Live Stage' else 'Watch-Party Live' end);
  return jsonb_build_object('eligible',true,'category',case when p_event.recipient_user_id=r.host_user_id then 'social_activity' else 'circle_activity' end,
    'notification_type','live_room_member_joined','title',name||case when p_event.recipient_user_id=r.host_user_id then ' joined your live' else ' joined a live' end,
    'body',room_title,'target_route',case when r.room_type='live' then '/watch-party/live-stage/[partyId]' else '/watch-party/[partyId]' end,
    'target_entity_id',r.party_id,'target_context',jsonb_build_object('display_context',jsonb_build_object('version',1,'actor_id',p_event.actor_user_id,
      'actor_display_name',name,'target_id',r.party_id,'subject_title',room_title)),
    'preference_key',case when p_event.recipient_user_id=r.host_user_id then 'social_activity_enabled' else 'circle_activity_enabled' end);
end $function$

CREATE OR REPLACE FUNCTION private.resolve_social_notification_before_subject_context(p_event notification_activity_events)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_actor text:=p_event.actor_user_id::text; v_recipient text:=p_event.recipient_user_id::text;
  v_context jsonb:=p_event.context; v_ok boolean:=false; v_row record; v_parent record;
  v_owner text; v_category text:='social_activity'; v_preference text:='social_activity_enabled';
  v_title text; v_body text; v_route text; v_target text; v_target_context jsonb:='{}';
begin
  if not private.social_notification_accounts_allowed(p_event.actor_user_id,p_event.recipient_user_id)
    or (p_event.expires_at is not null and p_event.expires_at<=now()) then
    return jsonb_build_object('eligible',false);
  end if;
  if p_event.event_kind='social_follow' then
    select true into v_ok from public.channel_followers
      where channel_user_id=v_recipient and follower_user_id=v_actor
        and channel_user_id||':'||follower_user_id=p_event.source_id
        and followed_at=(v_context->>'followedAt')::timestamptz;
    v_title:='New follower'; v_body:='Someone followed your Platform.';
    v_route:='/profile/[userId]'; v_target:=v_actor;
  elsif p_event.event_kind in ('social_follow_request','social_follow_accepted') then
    select * into v_row from public.channel_audience_requests
      where id::text=p_event.source_id and request_kind='follow'
        and channel_user_id=v_context->>'channelUserId'
        and requester_user_id=v_context->>'requesterUserId'
        and created_at=(v_context->>'createdAt')::timestamptz;
    if not found then return jsonb_build_object('eligible',false); end if;
    if p_event.event_kind='social_follow_request' then
      v_ok:=v_row.status='pending' and v_row.requester_user_id=v_actor and v_row.channel_user_id=v_recipient;
      v_title:='Follow request'; v_body:='You have a new follow request.';
      v_route:='/channel-settings';
    else
      v_ok:=v_row.status='approved' and v_row.channel_user_id=v_actor and v_row.requester_user_id=v_recipient
        and exists(select 1 from public.channel_followers where channel_user_id=v_actor and follower_user_id=v_recipient);
      v_title:='Follow request accepted'; v_body:='Your follow request was accepted.';
      v_route:='/channel/[userId]'; v_target:=v_actor;
    end if;
    v_target_context:=jsonb_build_object('requestId',p_event.source_id);
  elsif p_event.event_kind in ('circle_request','circle_accepted','circle_added') then
    select * into v_row from public.user_friendships
      where user_low_id=least(v_actor,v_recipient) and user_high_id=greatest(v_actor,v_recipient)
        and user_low_id||':'||user_high_id=p_event.source_id
        and requested_by_user_id=v_context->>'requestedBy'
        and created_at=(v_context->>'createdAt')::timestamptz;
    if not found then return jsonb_build_object('eligible',false); end if;
    v_category:='circle_activity'; v_preference:='circle_activity_enabled'; v_route:='/chilly-circle';
    if p_event.event_kind='circle_request' then
      v_ok:=v_row.status='pending' and v_row.requested_by_user_id=v_actor;
      v_title:='Chi''lly Circle request'; v_body:='You have a new Chi''lly Circle request.';
    elsif p_event.event_kind='circle_accepted' then
      v_ok:=v_row.status='active' and v_row.requested_by_user_id=v_recipient and v_row.actioned_by_user_id=v_actor
        and v_row.responded_at=(v_context->>'respondedAt')::timestamptz;
      v_title:='Chi''lly Circle request accepted'; v_body:='Your Chi''lly Circle request was accepted.';
    else
      v_ok:=v_row.status='active' and v_row.requested_by_user_id=v_actor and v_row.actioned_by_user_id=v_actor
        and v_row.responded_at=(v_context->>'respondedAt')::timestamptz;
      v_title:='Added to Chi''lly Circle'; v_body:='Someone added you to their Chi''lly Circle.';
    end if;
  elsif p_event.event_kind='content_shared' then
    v_ok:=exists(select 1 from public.user_content_relationships relation
        join public.user_profiles profile on profile.user_id=relation.user_id
        join public.titles title on title.id::text=relation.title_id
        where relation.user_id=v_actor and relation.title_id=p_event.source_id and relation.relationship_type='share'
          and relation.title_id=v_context->>'titleId' and profile.shares_visibility='public'
          and title.is_published is true and title.status='published'
          and (title.release_at is null or title.release_at<=now()))
      and public.is_active_chilly_circle_member(v_actor,v_recipient)
      and private.social_notification_profile_allowed(v_actor,p_event.recipient_user_id);
    v_category:='circle_activity'; v_preference:='circle_activity_enabled';
    v_title:='Chi''lly Circle shared activity'; v_body:='Someone in your Chi''lly Circle shared a title.';
    v_route:='/title/[id]'; v_target:=p_event.source_id;
    v_target_context:=jsonb_build_object('titleId',p_event.source_id,'defaultActionLabel','Open title');
  elsif p_event.event_kind in ('circle_post','profile_post_liked') then
    select id,user_id,visibility,moderation_status,deleted_at,created_at into v_row
      from public.profile_posts where id::text=p_event.source_id and id::text=v_context->>'postId';
    if not found then return jsonb_build_object('eligible',false); end if;
    v_ok:=v_row.deleted_at is null and v_row.visibility='public' and v_row.moderation_status in ('clean','reported')
      and private.social_notification_profile_allowed(v_row.user_id,p_event.recipient_user_id);
    if p_event.event_kind='circle_post' then
      v_ok:=v_ok and v_row.user_id=v_actor and v_row.created_at=(v_context->>'createdAt')::timestamptz
        and public.is_active_chilly_circle_member(v_actor,v_recipient);
      v_category:='circle_activity'; v_preference:='circle_activity_enabled';
      v_title:='New Chi''lly Circle post'; v_body:='Someone in your Chi''lly Circle posted an update.';
    else
      v_ok:=v_ok and v_row.user_id=v_recipient and exists(select 1 from public.profile_post_likes
        where post_id=v_row.id and user_id=v_actor and created_at=(v_context->>'createdAt')::timestamptz);
      v_title:='Your post was liked'; v_body:='Someone liked your profile post.';
    end if;
    v_route:='/profile/[userId]'; v_target:=v_row.user_id;
    v_target_context:=jsonb_build_object('postId',v_row.id);
  elsif p_event.event_kind in ('profile_comment','profile_reply','video_comment','video_reply') then
    if p_event.event_kind in ('profile_comment','profile_reply') then
      select id,post_id as content_id,user_id,parent_comment_id,created_at,deleted_at,moderation_status into v_row
        from public.profile_post_comments where id::text=p_event.source_id;
      if not found then return jsonb_build_object('eligible',false); end if;
      select post.user_id into v_owner from public.profile_posts post
        where post.id=v_row.content_id and post.id::text=v_context->>'postId'
          and post.deleted_at is null and post.visibility='public' and post.moderation_status in ('clean','reported');
      if not found or not private.social_notification_profile_allowed(v_owner,p_event.recipient_user_id)
      then return jsonb_build_object('eligible',false); end if;
      select id,user_id,post_id as content_id,deleted_at,moderation_status into v_parent
        from public.profile_post_comments where id=v_row.parent_comment_id;
      v_route:='/profile/[userId]'; v_target:=v_owner;
      v_target_context:=jsonb_build_object('postId',v_row.content_id,'commentId',v_row.id);
    else
      select id,video_id as content_id,user_id,parent_comment_id,created_at,deleted_at,moderation_status into v_row
        from public.creator_video_comments where id::text=p_event.source_id;
      if not found then return jsonb_build_object('eligible',false); end if;
      select owner_id::text into v_owner from public.videos
        where id=v_row.content_id and id::text=v_context->>'videoId';
      if not found or not private.social_notification_video_allowed(v_row.content_id,p_event.recipient_user_id)
      then return jsonb_build_object('eligible',false); end if;
      select id,user_id,video_id as content_id,deleted_at,moderation_status into v_parent
        from public.creator_video_comments where id=v_row.parent_comment_id;
      v_route:='/player/[id]'; v_target:=v_row.content_id::text;
      v_target_context:=jsonb_build_object('videoId',v_row.content_id,'commentId',v_row.id);
    end if;
    v_ok:=v_row.user_id=v_actor and v_row.deleted_at is null and v_row.moderation_status in ('clean','reported')
      and v_row.created_at=(v_context->>'createdAt')::timestamptz
      and v_row.parent_comment_id is not distinct from private.social_notification_uuid(v_context->>'parentCommentId');
    if v_row.parent_comment_id is not null then
      v_ok:=v_ok and v_parent.id=v_row.parent_comment_id and v_parent.content_id=v_row.content_id
        and v_parent.deleted_at is null and v_parent.moderation_status in ('clean','reported');
    end if;
    if p_event.event_kind in ('profile_reply','video_reply') then
      v_ok:=v_ok and v_row.parent_comment_id is not null and v_parent.user_id=v_recipient;
      v_title:='New reply'; v_body:='Someone replied to your comment.';
    else
      v_ok:=v_ok and v_owner=v_recipient;
      v_title:='New comment'; v_body:='Someone commented on your content.';
    end if;
    v_category:='reply_comment';
  elsif p_event.event_kind='chat_message' then
    select id,thread_id,sender_user_id,created_at,moderation_status,message_type into v_row
      from public.chat_messages where id::text=p_event.source_id;
    if not found then return jsonb_build_object('eligible',false); end if;
    v_ok:=v_row.sender_user_id=v_actor and v_row.thread_id::text=v_context->>'threadId'
      and v_row.created_at=(v_context->>'createdAt')::timestamptz
      and v_row.moderation_status='clean' and v_row.message_type='text'
      and exists(select 1 from public.chat_threads where id=v_row.thread_id)
      and exists(select 1 from public.chat_thread_members where thread_id=v_row.thread_id and user_id=v_actor)
      and exists(select 1 from public.chat_thread_members where thread_id=v_row.thread_id and user_id=v_recipient
        and (last_read_at is null or last_read_at<v_row.created_at));
    v_category:='new_message'; v_preference:='messages_enabled';
    v_title:='New Chi''lly Chat message'; v_body:='You have a new message.';
    v_route:='/chat/[threadId]'; v_target:=v_row.thread_id::text;
    v_target_context:=jsonb_build_object('threadId',v_row.thread_id,'messageId',v_row.id);
  else return jsonb_build_object('eligible',false); end if;
  if v_ok is not true then return jsonb_build_object('eligible',false); end if;
  return jsonb_build_object('eligible',true,'category',v_category,'notification_type',p_event.event_kind,
    'title',v_title,'body',v_body,'target_route',v_route,'target_entity_id',v_target,
    'target_context',v_target_context,'preference_key',v_preference);
end;
$function$

CREATE OR REPLACE FUNCTION private.room_start_notification_delivery_state(b private.room_start_notification_bindings)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare d private.room_start_notification_deliveries;
begin
  perform pg_advisory_xact_lock(hashtextextended('room-live-start:'||jsonb_build_array(b.party_id,b.room_generation,b.recipient_user_id)::text,0));
  select * into d from private.room_start_notification_deliveries
    where party_id=b.party_id and room_generation=b.room_generation and recipient_user_id=b.recipient_user_id;
  if not found then return 'unowned'; end if;
  if d.winner_event_id=b.event_id then return 'same'; end if;
  if d.in_app_delivered or not exists(select 1 from public.notification_activity_events where id=d.winner_event_id)
    or exists(select 1 from public.notification_activity_pushes where event_id=d.winner_event_id and status in ('sent','unknown'))
    then return 'delivered'; end if;
  if exists(select 1 from public.notification_activity_pushes where event_id=d.winner_event_id and status='sending') then return 'pending'; end if;
  -- Absence is not proof of no-send. Release only retained explicit provider
  -- rejection records, never an uncertain/lost result or retention tombstone.
  if exists(select 1 from public.notification_activity_pushes where event_id=d.winner_event_id)
    and not exists(select 1 from public.notification_activity_pushes where event_id=d.winner_event_id and status not in ('failed','retryable')) then
    delete from private.room_start_notification_deliveries where party_id=b.party_id and room_generation=b.room_generation and recipient_user_id=b.recipient_user_id;
    return 'unowned';
  end if;
  return 'delivered';
end $function$

CREATE OR REPLACE FUNCTION private.route_legacy_seat_notification_to_activity()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare p public.paid_live_watch_party_passes; s jsonb; buyer uuid;
begin
  if new.source_type is distinct from 'live_watch_party_seat'
    or new.notification_type is null or new.notification_type not in ('live_watch_party_seat_requested','live_watch_party_seat_approved','live_watch_party_seat_rejected')
    then return new; end if;
  -- Until delivery is explicitly configured, retain the existing working bell
  -- path. Source deployment alone must not silently consume these notices.
  if not exists(select 1 from public.notification_activity_worker_config where singleton and enabled)
    then return new; end if;
  -- Only the exact current state emitted by the existing authoritative paths
  -- can become work. Invalid legacy attempts cannot bypass preferences either.
  buyer:=case when new.notification_type='live_watch_party_seat_requested' then new.actor_user_id else new.user_id end;
  select * into p from public.paid_live_watch_party_passes where offer_id=private.seat_notification_uuid(new.source_id)
    and buyer_id=buyer and party_id=new.target_entity_id and status='active' and pass_type='live_watch_party_seat_pass';
  if not found then return null; end if;
  s:=private.seat_notification_source(new.notification_type,p.id);
  if not coalesce((s->>'eligible')::boolean,false) or s->>'recipient' is distinct from new.user_id::text
    or (new.actor_user_id is not null and s->>'actor' is distinct from new.actor_user_id::text)
    or (new.notification_type<>'live_watch_party_seat_approved' and new.actor_user_id is null)
    or new.target_route is distinct from '/watch-party/live-stage/[partyId]'
    or new.target_context->>'seat_state' is distinct from s->>'state'
    then return null; end if;
  perform private.enqueue_notification_activity('seat:'||p.id||':'||new.notification_type||':'||md5(s->>'revision'),
    new.notification_type,p.id::text,private.seat_notification_uuid(s->>'actor'),private.seat_notification_uuid(s->>'recipient'),
    jsonb_build_object('revision',s->>'revision','offerId',p.offer_id),now(),now()+interval '24 hours');
  return null;
end $function$

CREATE OR REPLACE FUNCTION private.sandbox_cashout_auction_binding(p_id uuid, p_qualification uuid)
 RETURNS text
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
declare m public.money_access_ledger_events; p public.provider_events; sq private.sandbox_cashout_qualifications;
 c private.auction_platform_settlement_contracts; i public.money_purchase_intents;
 v_lane text; receipt jsonb; quote jsonb; terminal boolean;
begin
 select * into m from public.money_access_ledger_events where id=p_id;
 select * into p from public.provider_events where id=m.provider_event_id;
 select * into sq from private.sandbox_cashout_qualifications where id=p_qualification;
 v_lane:=case p.provider when 'stripe_event_auction' then 'event' when 'stripe_room_auction' then 'room' end;
 if v_lane is null or m.id is null or p.id is null or sq.id is null then return null; end if;
 select * into c from private.auction_platform_settlement_contracts where lane=v_lane
  and purchase_intent_id::text=m.metadata->>'purchase_intent_id';
 if c.id is null or c.environment<>'test' or c.platform_account_id is distinct from sq.platform_account_id
  or c.recipient_account_id is distinct from sq.account_id or c.creator_id is distinct from sq.creator_id
  or c.creator_id is distinct from m.creator_id or c.buyer_id is distinct from m.user_id
  or c.amount_minor is distinct from m.amount_minor or c.currency is distinct from m.currency
  or m.environment is distinct from 'sandbox' or p.environment is distinct from 'sandbox'
  or m.source_type is distinct from (case v_lane when 'event' then 'event' else 'room_seat_auction' end)
  or m.metadata->>'auction_quote_id' is distinct from c.quote_id::text
  or m.metadata->>'provider_account_id' is distinct from c.platform_account_id
 then return null; end if;
 select * into i from public.money_purchase_intents where id=c.purchase_intent_id;
 if i.id is null or i.status<>'consumed' or i.environment<>'sandbox' or i.provider is distinct from p.provider
  or i.user_id is distinct from m.user_id or i.creator_id is distinct from m.creator_id
  or i.product_id is distinct from m.product_id or i.source_id is distinct from m.source_id
  or i.source_type is distinct from m.source_type or i.amount_minor is distinct from m.amount_minor or i.currency is distinct from 'usd'
  or i.provider_product_id is distinct from c.platform_product_id then return null; end if;
 if v_lane='event' then
  select to_jsonb(q) into quote from private.creator_event_auction_quotes q where q.id=c.quote_id;
  select to_jsonb(r) into receipt from private.creator_event_auction_receipts r where r.ledger_event_id=m.id
   and r.provider_record_id=p.id and r.outcome='paid' and r.resolution='fulfilled' and r.environment='test'
   and r.provider_account_id=c.platform_account_id and r.payload_hash=p.raw_payload_hash
   and p.provider_event_id=r.provider_account_id||':'||r.provider_event_id order by r.created_at,r.id limit 1;
  select exists(select 1 from private.creator_event_auction_receipts r where r.quote_id=c.quote_id
   and r.environment='test' and r.provider_account_id=c.platform_account_id and r.outcome in ('refunded','disputed')
   and r.ledger_event_id is not null) into terminal;
 else
  select to_jsonb(q) into quote from private.creator_room_auction_quotes q where q.id=c.quote_id;
  select to_jsonb(r) into receipt from private.creator_room_auction_receipts r where r.ledger_event_id=m.id
   and r.provider_record_id=p.id and r.outcome='paid' and r.resolution='fulfilled' and r.environment='test'
   and r.provider_account_id=c.platform_account_id and r.payload_hash=p.raw_payload_hash
   and p.provider_event_id=r.provider_account_id||':'||r.provider_event_id order by r.created_at,r.id limit 1;
  select exists(select 1 from private.creator_room_auction_receipts r where r.quote_id=c.quote_id
   and r.environment='test' and r.provider_account_id=c.platform_account_id and r.outcome in ('refunded','disputed')
   and r.ledger_event_id is not null) into terminal;
 end if;
 if quote is null or receipt is null or terminal
  or quote->>'environment' is distinct from 'test' or quote->>'provider_account_id' is distinct from c.recipient_account_id
  or quote->>'buyer_id' is distinct from c.buyer_id::text or quote->>'creator_id' is distinct from c.creator_id::text
  or quote->>'capability_id' is distinct from c.capability_id::text
  or quote->>'amount_minor' is distinct from c.amount_minor::text or quote->>'currency' is distinct from c.currency
  or quote->>'auction_id' is distinct from m.metadata->>'auction_id'
  or quote->>'session_id' is distinct from i.session_generation or quote->>'purchase_intent_id' is distinct from i.id::text
  or quote->>'checkout_attempt_id' is distinct from i.checkout_attempt_id::text or quote->>'superseded_at' is not null
  or quote->>'provider_payment_intent_id' is distinct from receipt->>'payment_intent_id'
  or m.metadata->>'original_transaction_id' is distinct from receipt->>'payment_intent_id'
  or receipt->>'quote_id' is distinct from c.quote_id::text
  or receipt#>>'{evidence,settlementContractId}' is distinct from c.id::text
  or receipt#>>'{evidence,settlementPolicy}' is distinct from c.policy_version
  or receipt#>>'{evidence,providerProductId}' is distinct from c.platform_product_id
  or receipt#>>'{evidence,checkoutSessionId}' is distinct from quote->>'provider_checkout_session_id'
 then return null; end if;
 return md5(to_jsonb(c)::text||quote::text||receipt::text||to_jsonb(i)::text);
end; $function$

CREATE OR REPLACE FUNCTION private.sandbox_cashout_recovery_admission()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare e private.sandbox_cashout_executions; q private.sandbox_cashout_qualifications; target uuid;
begin
 if tg_table_name='sandbox_cashout_recovery_revocations' then
  select execution_id into target from private.sandbox_cashout_recovery_authorities where id=new.authority_id;
 else target:=new.execution_id; end if;
 select * into e from private.sandbox_cashout_executions where id=target;
 if e.id is null then raise exception 'sandbox_recovery_execution_required'; end if;
 perform private.lock_sandbox_cashout_creator(e.creator_id);
 select * into e from private.sandbox_cashout_executions where id=target for update;
 if tg_table_name='sandbox_cashout_recovery_revocations' then return new; end if;
 select * into q from private.sandbox_cashout_qualifications where id=e.qualification_id;
 if not ((new.stage='reversal' and e.phase='return_confirmed' and e.returned_minor=e.bank_minor)
  or (new.stage='funding_return' and e.phase='funding_return_pending' and e.payout_id is null))
  or e.transfer_id is null or new.transfer_id is distinct from e.transfer_id
  or new.account_id is distinct from q.account_id or new.platform_account_id is distinct from q.platform_account_id
  or new.original_transfer_minor<>e.bank_minor or new.prior_returned_minor<>0 or new.recoverable_minor<>e.bank_minor
  or new.verified_at>clock_timestamp() or new.verified_at<clock_timestamp()-interval '5 minutes' or new.expires_at<=clock_timestamp()
 then raise exception 'sandbox_recovery_binding_invalid'; end if;
 return new;
end; $function$

CREATE OR REPLACE FUNCTION private.sandbox_cashout_revoke_admission()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare creator uuid;
begin
 select creator_id into strict creator from private.sandbox_cashout_qualifications where id=new.qualification_id;
 perform private.lock_sandbox_cashout_creator(creator);
 return new;
end; $function$

CREATE OR REPLACE FUNCTION private.sandbox_cashout_source(p_id uuid, p_qualification uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
declare m public.money_access_ledger_events; p public.provider_events; q private.sandbox_cashout_qualifications;
 product public.monetization_products; provider_product public.monetization_products; intent public.money_purchase_intents;
 store_mapping public.monetization_product_store_mappings;
 net bigint; h text; auction_binding text; tip_binding text; platform_bps integer;
begin
 select * into m from public.money_access_ledger_events where id=p_id;
 select * into q from private.sandbox_cashout_qualifications where id=p_qualification;
 select * into p from public.provider_events where id=m.provider_event_id;
 if m.id is null or p.id is null or q.id is null or m.creator_id is distinct from q.creator_id or m.user_id is null
 or m.user_id=m.creator_id or m.environment<>'sandbox' or m.currency<>'usd' or m.payable_state<>'not_payable'
 or m.status not in ('sandbox_only','verified') or m.amount_minor<=0 or p.environment<>'sandbox'
 or p.status<>'processed' or p.user_id is distinct from m.user_id
 or p.provider not in ('revenuecat_app_store','revenuecat_google_play','google_play','revenuecat','stripe_physical_goods','stripe_event_auction','stripe_room_auction')
 or m.event_type not in ('INITIAL_PURCHASE','NON_RENEWING_PURCHASE','RENEWAL','checkout.session.completed','checkout.session.async_payment_succeeded')
 or exists(select 1 from public.money_access_ledger_events t where t.environment='sandbox'
   and t.creator_id=m.creator_id and t.user_id=m.user_id and t.source_type is not distinct from m.source_type
   and t.source_id is not distinct from m.source_id
   and (nullif(m.metadata->>'original_transaction_id','') is null
     or t.metadata->>'original_transaction_id'=m.metadata->>'original_transaction_id')
   and (t.payable_state in ('refunded','reversed','chargeback') or t.status in ('refunded','reversed','chargeback')
     or t.event_type in ('REFUND','REVOCATION','charge.refunded','charge.dispute.created')))
 then return null; end if;
 if p.provider in ('stripe_event_auction','stripe_room_auction') then
  auction_binding:=private.sandbox_cashout_auction_binding(m.id,q.id);
  if auction_binding is null then return null; end if;
 end if;
 -- Native tips retain the existing no-app-commission contract. Ledger amount is
 -- canonical buyer gross, not a pre-deducted creator share. A client metadata
 -- label cannot select this exception: source, catalog, provider and consumed
 -- intent must all agree on the immutable original purchase identity.
 select * into product from public.monetization_products where id=m.product_id;
 select * into provider_product from public.monetization_products where id=p.product_id;
 select * into intent from public.money_purchase_intents where id::text=m.metadata->>'purchase_intent_id';
 select * into store_mapping from public.monetization_product_store_mappings where id::text=intent.metadata->>'store_mapping_id';
 platform_bps:=q.simulated_platform_bps;
 if m.source_type='creator_tip' or product.product_type='creator_tip' or provider_product.product_type='creator_tip'
  or intent.source_type='creator_tip' or intent.product_type='creator_tip' then
  if m.source_type is distinct from 'creator_tip' or product.product_type is distinct from 'creator_tip'
   or provider_product.product_type is distinct from 'creator_tip' or intent.product_type is distinct from 'creator_tip'
   or intent.source_type is distinct from 'creator_tip' or product.id is null or intent.id is null
   or p.product_id is distinct from m.product_id or intent.product_id is distinct from m.product_id
   or p.provider not in ('revenuecat_app_store','revenuecat_google_play','google_play','revenuecat')
   or intent.provider is distinct from p.provider
   or p.metadata->>'purchase_intent_id' is distinct from m.metadata->>'purchase_intent_id'
   or nullif(m.metadata->>'original_transaction_id','') is null
   or p.metadata->>'original_transaction_id' is distinct from m.metadata->>'original_transaction_id'
   or intent.provider_product_id is distinct from p.metadata->>'provider_product_id'
   or intent.provider_product_id is distinct from m.metadata->>'provider_product_id'
   or intent.status is distinct from 'consumed' or intent.environment is distinct from 'sandbox'
   or intent.user_id is distinct from m.user_id or intent.creator_id is distinct from m.creator_id
   or intent.source_id is distinct from m.source_id or m.source_id is distinct from m.creator_id
   or intent.amount_minor is distinct from m.amount_minor or intent.currency is distinct from m.currency
  then return null; end if;
  -- iOS uses a conceptual internal_setup catalog plus a finite sandbox store
  -- mapping; Android's existing native catalog directly binds the provider SKU.
  if p.provider='revenuecat_app_store' then
   if store_mapping.id is null or store_mapping.product_id is distinct from product.id
    or store_mapping.concept is distinct from 'creator_tip' or store_mapping.platform is distinct from 'ios'
    or store_mapping.provider is distinct from p.provider or store_mapping.environment is distinct from 'sandbox'
    or store_mapping.provider_product_id is distinct from intent.provider_product_id
    or p.metadata->>'store_mapping_id' is distinct from store_mapping.id::text
   then return null; end if;
  elsif product.provider is distinct from p.provider or product.environment is distinct from 'sandbox'
   or product.provider_product_id is distinct from intent.provider_product_id then return null;
  end if;
  if not exists(select 1 from public.revenuecat_consumable_transaction_intents t
   where t.provider=p.provider and t.original_transaction_id=p.metadata->>'original_transaction_id'
    and t.purchase_intent_id=intent.id and t.binding_state='exact' and not t.terminal)
  then return null; end if;
  platform_bps:=0;
  tip_binding:=jsonb_build_object('productId',product.id,'productType',product.product_type,'provider',product.provider,
   'providerProductId',product.provider_product_id,'intentId',intent.id,'sourceType',intent.source_type,
   'sourceId',intent.source_id,'buyerId',intent.user_id,'creatorId',intent.creator_id,'amountMinor',intent.amount_minor,
   'currency',intent.currency,'environment',intent.environment,'storeMappingId',store_mapping.id,
   'originalTransactionId',p.metadata->>'original_transaction_id')::text;
 end if;
 net:=m.amount_minor::bigint-((m.amount_minor::bigint*q.simulated_tax_bps+9999)/10000)
 -((m.amount_minor::bigint*platform_bps+9999)/10000)
 -((m.amount_minor::bigint*q.simulated_provider_bps+9999)/10000)-q.simulated_provider_fixed_minor;
 if net<=0 or net>2147483647 then return null; end if;
 h:=md5(to_jsonb(m)::text||to_jsonb(p)::text||coalesce(auction_binding,'')||coalesce(tip_binding,''));
 return jsonb_build_object('netMinor',net,'sourceHash',h);
end; $function$

CREATE OR REPLACE FUNCTION private.seat_notification_source(p_kind text, p_pass_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare p public.paid_live_watch_party_passes; r public.watch_party_rooms;
  m public.watch_party_room_memberships; o public.paid_live_watch_party_offers;
  revision timestamptz; actor_id uuid; recipient_id uuid; state text;
begin
  if p_kind is null or p_kind not in ('live_watch_party_seat_requested','live_watch_party_seat_approved','live_watch_party_seat_rejected')
    then return '{"eligible":false}'; end if;
  select * into p from public.paid_live_watch_party_passes where id=p_pass_id;
  if not found or p.pass_type<>'live_watch_party_seat_pass' or p.status<>'active'
    or p.revoked_at is not null or p.refunded_at is not null then return '{"eligible":false}'; end if;
  select * into r from public.watch_party_rooms where party_id=p.party_id;
  if not found or r.room_type<>'live' or not r.is_active or r.host_user_id is distinct from p.creator_id
    or r.host_user_id=p.buyer_id then return '{"eligible":false}'; end if;
  select * into o from public.paid_live_watch_party_offers where id=p.offer_id;
  if not found or o.party_id<>p.party_id or o.creator_id<>p.creator_id or o.pass_type<>p.pass_type
    or not public.has_exact_live_watch_party_pass_internal(p.party_id,p.buyer_id,p.pass_type)
    then return '{"eligible":false}'; end if;
  select * into m from public.watch_party_room_memberships where party_id=p.party_id and user_id=p.buyer_id::text;
  if not found or m.membership_state not in ('active','reconnecting') or m.left_at is not null
    then return '{"eligible":false}'; end if;
  if exists(select 1 from public.paid_live_watch_party_offers access_offer where access_offer.party_id=p.party_id
    and access_offer.pass_type='live_watch_party_access_pass' and access_offer.status in ('sandbox','active')
    and (access_offer.starts_at is null or access_offer.starts_at<=now())
    and (access_offer.ends_at is null or access_offer.ends_at>now()))
    and not public.has_exact_live_watch_party_pass_internal(p.party_id,p.buyer_id,'live_watch_party_access_pass')
    then return '{"eligible":false}'; end if;
  if p_kind='live_watch_party_seat_requested' then
    if p.requested_at is null or p.approved_at is not null or p.rejected_at is not null
      or m.stage_role<>'listener' then return '{"eligible":false}'; end if;
    revision:=p.requested_at; actor_id:=p.buyer_id; recipient_id:=p.creator_id; state:='requested';
  elsif p_kind='live_watch_party_seat_approved' then
    if p.approved_at is null or p.requested_at is not null or p.rejected_at is not null
      or m.stage_role<>'speaker' or not m.can_speak then return '{"eligible":false}'; end if;
    revision:=p.approved_at; actor_id:=p.creator_id; recipient_id:=p.buyer_id; state:='approved';
  else
    if p.rejected_at is null or p.requested_at is not null or p.approved_at is not null
      or m.stage_role<>'listener' then return '{"eligible":false}'; end if;
    revision:=p.rejected_at; actor_id:=p.creator_id; recipient_id:=p.buyer_id; state:='rejected';
  end if;
  return jsonb_build_object('eligible',true,'actor',actor_id,'recipient',recipient_id,
    'partyId',p.party_id,'offerId',p.offer_id,'revision',revision,'state',state);
end $function$

CREATE OR REPLACE FUNCTION private.social_notification_video_allowed(p_video_id uuid, p_recipient uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_owner uuid; v_visibility text; v_moderation text; v_scan text; v_quarantined timestamptz;
  v_vip boolean; v_paid boolean; v_pass public.creator_vip_passes%rowtype;
  v_identity jsonb; v_subscription public.creator_channel_subscriptions%rowtype;
begin
  select owner_id,visibility,moderation_status,scan_status,quarantined_at,vip_access_required
    into v_owner,v_visibility,v_moderation,v_scan,v_quarantined,v_vip
  from public.videos where id=p_video_id;
  if not found or p_recipient is null
    or not exists(select 1 from auth.users where id=p_recipient)
    or public.is_account_access_restricted(v_owner::text)
    or public.is_account_access_restricted(p_recipient::text)
    or public.has_channel_audience_block_between(v_owner::text,p_recipient::text)
    or v_moderation not in ('clean','reported') or v_quarantined is not null
  then return false; end if;
  if v_owner=p_recipient then return true; end if;
  if not public.media_scan_public_safe(v_scan)
    or not (v_visibility='public' or (v_visibility='circle'
      and public.is_active_chilly_circle_member(v_owner::text,p_recipient::text)))
  then return false; end if;
  if v_vip then
    if v_visibility<>'public' then return false; end if;
    select pass.* into v_pass from public.creator_vip_passes pass
      join public.creator_vip_pass_offers offer on offer.id=pass.offer_id and offer.creator_id=pass.creator_id
      where pass.creator_id=v_owner and pass.fan_id=p_recipient and pass.status='active'
        and pass.access_grant_id is not null and pass.activated_at is not null
        and pass.expires_at=pass.activated_at+interval '30 days'
        and pass.activated_at<=now() and pass.expires_at>now()
        and pass.refunded_at is null and pass.revoked_at is null and offer.status<>'blocked'
      order by pass.activated_at desc,pass.id desc limit 1;
    if not found then return false; end if;
    begin
      v_identity:=public.creator_money_historical_purchase_identity_internal(
        p_recipient,'vip_pass',v_pass.offer_id,v_pass.access_grant_id);
    exception when raise_exception then
      if sqlerrm='historical_purchase_identity_missing' then v_identity:=null; else raise; end if;
    end;
    return nullif(v_identity->>'accessGrantId','') is not null
      and private.social_notification_uuid(v_identity->>'accessGrantId')=v_pass.access_grant_id;
  end if;
  select is_paid into v_paid from public.creator_content_prices
    where content_type='creator_video' and content_id=p_video_id and creator_id=v_owner
    order by updated_at desc,id desc limit 1;
  if not coalesce(v_paid,false) then return true; end if;
  if v_visibility<>'public' then return false; end if;
  begin
    v_identity:=public.creator_video_existing_purchase_identity_internal(p_recipient,p_video_id);
  exception when raise_exception then
    if sqlerrm='historical_purchase_identity_missing' then v_identity:=null; else raise; end if;
  end;
  if nullif(v_identity->>'id','') is not null and nullif(v_identity->>'accessGrantId','') is not null then return true; end if;
  for v_subscription in select subscription.* from public.creator_channel_subscriptions subscription
    join public.creator_channel_subscription_offers offer
      on offer.id=subscription.offer_id and offer.creator_id=subscription.creator_id
    where subscription.creator_id=v_owner and subscription.subscriber_id=p_recipient
      and subscription.status in ('active','trialing','grace_period','cancel_pending')
      and subscription.current_period_end>now() and subscription.access_grant_id is not null
      and subscription.revoked_at is null and subscription.expired_at is null and offer.status<>'blocked'
    order by subscription.updated_at desc,subscription.id desc
  loop
    begin
      v_identity:=public.creator_money_historical_purchase_identity_internal(
        p_recipient,'channel_subscription',v_subscription.offer_id,v_subscription.access_grant_id);
    exception when raise_exception then
      if sqlerrm='historical_purchase_identity_missing' then v_identity:=null; else raise; end if;
    end;
    if nullif(v_identity->>'accessGrantId','') is not null
      and private.social_notification_uuid(v_identity->>'accessGrantId')=v_subscription.access_grant_id
    then return true; end if;
  end loop;
  return false;
end;
$function$

CREATE OR REPLACE FUNCTION public.cancel_undispatched_sandbox_creator_cashout(p_request_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare u uuid:=private.sandbox_cashout_current_user(); e private.sandbox_cashout_executions;
begin
 perform private.lock_sandbox_cashout_creator(u);
 select * into e from private.sandbox_cashout_executions where id=p_request_id and creator_id=u for update;
 if e.id is null then raise exception 'sandbox_cashout_not_found'; end if;
 if e.phase='prepared' then update private.sandbox_cashout_executions set phase='canceled' where id=e.id;
 elsif e.phase='funded' and e.payout_id is null then update private.sandbox_cashout_executions set phase='funding_return_pending' where id=e.id;
 elsif e.phase not in ('canceled','funding_return_pending','funding_return_unknown','returned') then raise exception 'sandbox_cashout_cannot_cancel'; end if;
 return private.sandbox_cashout_summary(e.id);
end; $function$

CREATE OR REPLACE FUNCTION public.claim_sandbox_creator_cashout_dispatch(p_request_id uuid, p_stage text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare e private.sandbox_cashout_executions; q private.sandbox_cashout_qualifications; tok uuid:=gen_random_uuid(); recovery uuid;
begin
 select * into e from private.sandbox_cashout_executions where id=p_request_id;
 if e.id is null then raise exception 'sandbox_cashout_not_found'; end if;
 perform private.lock_sandbox_cashout_creator(e.creator_id);
 select * into e from private.sandbox_cashout_executions where id=p_request_id for update;
 if p_stage is null or not ((p_stage='funding' and e.phase='prepared') or (p_stage='payout' and e.phase='funded')
 or (p_stage='reversal' and e.phase='return_confirmed') or (p_stage='funding_return' and e.phase='funding_return_pending'))
 then return jsonb_build_object('claimed',false,'token',tok); end if;
 perform 1 from private.sandbox_cashout_control where singleton for share;
 perform 1 from public.platform_money_kill_switches where key in
  ('live_money_enabled','payouts_enabled','cashout_enabled','stripe_connect_enabled','creator_monetization_enabled','provider_webhooks_enabled')
  order by key for share;
 if not private.sandbox_cashout_enabled() then raise exception 'sandbox_payout_execution_disabled'; end if;
 select * into q from private.sandbox_cashout_qualifications where id=e.qualification_id;
 if not exists(select 1 from public.creator_payout_accounts a where a.creator_user_id=e.creator_id::text
  and a.provider='stripe_connect' and a.provider_environment='test' and a.provider_account_id=q.account_id)
 then raise exception 'sandbox_cashout_provider_qualification_required'; end if;
 if q.verified_at>clock_timestamp() or q.expires_at<=clock_timestamp()
 or exists(select 1 from private.sandbox_cashout_revocations where qualification_id=q.id) then
  if p_stage not in ('reversal','funding_return') then raise exception 'sandbox_cashout_provider_qualification_required'; end if;
  recovery:=private.sandbox_cashout_recovery_current(e.id,p_stage);
  if recovery is null then raise exception 'sandbox_recovery_authority_required'; end if;
 end if;
 if p_stage in ('funding','payout') then
  -- Freeze every current subject/cohort authority row until the durable claim
  -- commits. Revocation that committed first is re-read after these waits.
  perform 1 from auth.users where id=e.creator_id for share;
  perform 1 from auth.sessions where id=e.originating_session_id and user_id=e.creator_id for share;
  perform 1 from public.sandbox_monetization_testers where user_id=e.creator_id::text for share;
  perform 1 from public.beta_access_memberships where user_id=e.creator_id::text for share;
  perform 1 from public.platform_role_memberships where user_id=e.creator_id::text for share;
  if not private.sandbox_cashout_subject_current(e.creator_id,e.originating_session_id) then raise exception 'sandbox_origin_tester_required'; end if;
  if e.source_hold or exists(select 1 from private.sandbox_cashout_allocations a where a.execution_id=e.id
   and (private.sandbox_cashout_source(a.money_ledger_id,q.id)->>'sourceHash') is distinct from a.source_hash)
   or exists(select 1 from private.sandbox_cashout_merch_allocations a where a.execution_id=e.id
    and (private.sandbox_cashout_merch_source(a.order_id,q.id)->>'sourceHash') is distinct from a.source_hash)
  then raise exception 'sandbox_source_reconciliation_required'; end if;
 end if;
 update private.sandbox_cashout_executions set phase=case p_stage when 'funding' then 'funding_unknown' when 'payout' then 'payout_unknown'
 when 'funding_return' then 'funding_return_unknown' else 'reversal_unknown' end,dispatch_token=tok,dispatched_at=clock_timestamp(),
 recovery_authority_id=coalesce(recovery,recovery_authority_id) where id=e.id;
 return jsonb_build_object('claimed',true,'token',tok);
end; $function$

CREATE OR REPLACE FUNCTION public.complete_notification_activity_push(p_event_id uuid, p_lease_token uuid, p_push_token_id uuid, p_status text, p_provider_message_id text DEFAULT NULL::text, p_error_code text DEFAULT NULL::text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_event public.notification_activity_events; v_push public.notification_activity_pushes;
begin
  if p_status not in ('sent','failed','unknown') or coalesce(p_error_code,'') !~ '^[a-zA-Z0-9_.:-]{0,80}$'
    or (p_provider_message_id is not null and p_provider_message_id !~ '^[a-zA-Z0-9_-]{1,128}$') then return false; end if;
  select * into v_event from public.notification_activity_events where id=p_event_id for update;
  if not found or v_event.lease_token is distinct from p_lease_token or v_event.status<>'leased' or v_event.lease_until<=now()
    then return false; end if;
  update public.notification_activity_pushes set status=case
      when p_status='failed' and p_error_code='MessageRateExceeded' and attempts<3 then 'retryable' else p_status end,
    retry_after=case when p_status='failed' and p_error_code='MessageRateExceeded' and attempts<3
      then now()+make_interval(secs=>60*(2^(attempts-1))::integer) else null end,
    provider_message_id=p_provider_message_id,error_code=p_error_code,completed_at=now()
    where event_id=p_event_id and push_token_id=p_push_token_id and lease_token=p_lease_token and status='sending'
    returning * into v_push;
  if not found then return false; end if;
  insert into public.notification_delivery_attempts(id,notification_id,recipient_user_id,push_token_id,provider,
    provider_message_id,status,error_code)
  values(gen_random_uuid(),v_event.notification_id,v_event.recipient_user_id,p_push_token_id,'expo',p_provider_message_id,
    case when p_status='sent' then 'sent' else 'failed' end,case when p_status='unknown' then 'delivery_unknown' else p_error_code end);
  if p_error_code='DeviceNotRegistered' then
    update public.user_push_tokens set enabled=false,revoked_at=now(),updated_at=now()
      where id=p_push_token_id and user_id=v_event.recipient_user_id and token_fingerprint=v_push.token_fingerprint;
  end if;
  return true;
end $function$

CREATE OR REPLACE FUNCTION public.finish_notification_activity(p_event_id uuid, p_lease_token uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_event public.notification_activity_events; v_retry_after timestamptz;
begin
  select * into v_event from public.notification_activity_events where id=p_event_id for update;
  if not found or v_event.status<>'leased' or v_event.lease_token is distinct from p_lease_token
    or v_event.lease_until<=now() or v_event.materialized_at is null then return false; end if;
  if exists(select 1 from public.notification_activity_pushes p where p.event_id=p_event_id and p.status='sending')
    then return false; end if;
  select min(retry_after) into v_retry_after from public.notification_activity_pushes
    where event_id=p_event_id and status='retryable';
  if v_retry_after is not null then
    update public.notification_activity_events set status='pending',scheduled_at=greatest(now(),v_retry_after),
      lease_token=null,lease_until=null where id=p_event_id;
    return false;
  end if;
  update public.notification_activity_events set status='complete',completed_at=now(),lease_until=null
    where id=p_event_id and status='leased' and lease_token=p_lease_token and lease_until>now()
      and materialized_at is not null and not exists(select 1 from public.notification_activity_pushes p
        where p.event_id=p_event_id and p.status='sending');
  return found;
end $function$

CREATE OR REPLACE FUNCTION public.get_sandbox_creator_cashout_execution_context(p_request_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare e private.sandbox_cashout_executions; q private.sandbox_cashout_qualifications;
begin
 select * into e from private.sandbox_cashout_executions where id=p_request_id;
 if e.id is null then raise exception 'sandbox_cashout_not_found'; end if;
 select * into q from private.sandbox_cashout_qualifications where id=e.qualification_id;
 return jsonb_build_object('requestId',e.id,'executionId',e.id,'platformAccountId',q.platform_account_id,
 'accountId',q.account_id,'destinationId',q.destination_id,'environment','test','method',case when q.payout_type='scheduled' then 'standard' else 'instant' end,
 'sourceType',q.source_type,'grossMinor',e.gross_minor,'appFeeMinor',e.app_fee_minor,'expectedProviderFeeMinor',e.expected_provider_fee_minor,
 'bankMinor',e.bank_minor,'currency','usd','phase',e.phase,'transferId',e.transfer_id,'payoutId',e.payout_id,'reversalId',e.reversal_id,
 'dispatchKey','cw-cashout-'||e.id::text,'dispatchedAt',floor(extract(epoch from e.dispatched_at)),'inlineKnownZeroQualified',false);
end; $function$

CREATE OR REPLACE FUNCTION public.prepare_notification_activity(p_event_id uuid, p_lease_token uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare e public.notification_activity_events;b private.room_start_notification_bindings;result jsonb;state text;
begin
  select * into e from public.notification_activity_events where id=p_event_id;
  b:=private.current_room_start_notification_binding(e);
  if b.event_id is null or e.status<>'leased' or e.lease_token is distinct from p_lease_token or e.lease_until<=now()
    then return public.prepare_notification_activity_pre_room_start(p_event_id,p_lease_token); end if;
  perform 1 from public.watch_party_rooms where party_id=b.party_id for share;
  b:=private.current_room_start_notification_binding(e);
  if b.event_id is null then return public.prepare_notification_activity_pre_room_start(p_event_id,p_lease_token); end if;
  state:=private.room_start_notification_delivery_state(b);
  if private.resolve_notification_activity(e)->>'eligible'='true' and state in ('delivered','pending')
    then return private.defer_duplicate_room_start(e,state); end if;
  result:=public.prepare_notification_activity_pre_room_start(p_event_id,p_lease_token);
  select * into e from public.notification_activity_events where id=p_event_id;
  if result->>'eligible'='true' and e.notification_id is not null and e.materialized_at is not null and exists(
    select 1 from public.notifications n where n.id=e.notification_id and n.user_id=e.recipient_user_id
      and n.source_type='notification_activity' and n.source_id=e.id::text) then
    insert into private.room_start_notification_deliveries(party_id,room_generation,recipient_user_id,winner_event_id,in_app_delivered)
      values(b.party_id,b.room_generation,b.recipient_user_id,e.id,true)
      on conflict(party_id,room_generation,recipient_user_id) do update set in_app_delivered=true
      where room_start_notification_deliveries.winner_event_id=excluded.winner_event_id;
  end if;
  return result;
end $function$

CREATE OR REPLACE FUNCTION public.prepare_notification_activity_pre_room_start(p_event_id uuid, p_lease_token uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_event public.notification_activity_events; v_plan jsonb; v_id uuid; v_tokens jsonb;
begin
  select * into v_event from public.notification_activity_events where id=p_event_id for update;
  if not found or v_event.status<>'leased' or v_event.lease_token is distinct from p_lease_token or v_event.lease_until<=now()
    then return '{"eligible":false,"reason":"stale_lease"}'::jsonb; end if;
  v_plan:=private.resolve_notification_activity(v_event);
  if coalesce((v_plan->>'eligible')::boolean,false) is false then
    update public.notification_activity_events set status='suppressed',completed_at=now() where id=v_event.id;
    return '{"eligible":false,"reason":"source_or_preference_changed"}'::jsonb;
  end if;
  if v_event.materialized_at is null then
    if (v_plan->>'in_app_allowed')::boolean then
      insert into public.notifications(user_id,actor_user_id,category,notification_type,title,body,
        target_route,target_entity_id,target_context,deep_link,source_type,source_id,status,delivered_at)
      values(v_event.recipient_user_id,v_event.actor_user_id,v_plan->>'category',v_plan->>'notification_type',
        v_plan->>'title',v_plan->>'body',v_plan->>'target_route',v_plan->>'target_entity_id',
        coalesce(v_plan->'target_context','{}'),v_plan->>'deep_link','notification_activity',v_event.id::text,'sent',now())
      returning id into v_id;
    end if;
    update public.notification_activity_events set notification_id=v_id,materialized_at=now()
      where id=v_event.id returning * into v_event;
  end if;
  -- A rate-limit rejection is known not to have been sent. A later worker may
  -- retry only the same currently owned token, after backoff, up to three sends.
  update public.notification_activity_pushes d set status='failed',retry_after=null,
    error_code='delivery_no_longer_eligible',completed_at=now()
    where d.event_id=v_event.id and d.status='retryable' and
      (not (v_plan->>'push_allowed')::boolean or not exists (
        select 1 from public.user_push_tokens p where p.id=d.push_token_id
          and p.token_fingerprint=d.token_fingerprint
          and private.notification_activity_token_current(p,v_event.recipient_user_id)));
  select coalesce(jsonb_agg(t.id),'[]') into v_tokens from (
    select p.id,row_number() over(partition by p.platform order by p.last_seen_at desc,p.id) ordinal from public.user_push_tokens p
    where (v_plan->>'push_allowed')::boolean and private.notification_activity_token_current(p,v_event.recipient_user_id)
      and (not exists(select 1 from public.notification_activity_pushes d where d.event_id=v_event.id and d.push_token_id=p.id)
        or exists(select 1 from public.notification_activity_pushes d where d.event_id=v_event.id and d.push_token_id=p.id
          and d.status='retryable' and d.attempts<3 and d.retry_after<=now()
          and d.lease_token is distinct from p_lease_token and d.token_fingerprint=p.token_fingerprint))
  ) t where t.ordinal<=5;
  return jsonb_build_object('eligible',true,'tokenIds',v_tokens);
end $function$

CREATE OR REPLACE FUNCTION public.preview_sandbox_creator_cashout(p_amount_minor integer, p_payout_type text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare u uuid:=private.sandbox_cashout_current_user(); q private.sandbox_cashout_qualifications;
 app_fee bigint; bank bigint; fee bigint; available bigint; merch_available bigint;
begin
 if p_amount_minor is null or p_amount_minor<=0 or p_payout_type is null or p_payout_type not in ('scheduled','instant') then raise exception 'cashout_input_invalid'; end if;
 if not private.sandbox_cashout_enabled() then return jsonb_build_object('ready',false,'reason','sandbox_payout_execution_disabled','environment','test','financialAuthority',false); end if;
 select * into q from private.sandbox_cashout_qualifications a where creator_id=u and payout_type=p_payout_type
 and verified_at<=clock_timestamp() and expires_at>clock_timestamp()
 and not exists(select 1 from private.sandbox_cashout_revocations r where r.qualification_id=a.id)
 and exists(select 1 from public.creator_payout_accounts c where c.creator_user_id=u::text
  and c.provider='stripe_connect' and c.provider_environment='test' and c.provider_account_id=a.account_id)
 order by verified_at desc,id desc limit 1;
 if q.id is null then return jsonb_build_object('ready',false,'reason','sandbox_cashout_provider_qualification_required','environment','test','financialAuthority',false); end if;
 select coalesce(sum(greatest(0,(private.sandbox_cashout_source(m.id,q.id)->>'netMinor')::bigint
 -coalesce((select sum(a.amount_minor-coalesce(r.released_minor,0)) from private.sandbox_cashout_allocations a join private.sandbox_cashout_executions e on e.id=a.execution_id
 left join private.sandbox_cashout_simulated_return_accounting r on r.execution_id=a.execution_id and r.money_ledger_id=a.money_ledger_id
 where a.money_ledger_id=m.id and e.phase<>'canceled'),0))),0)
 into available from public.money_access_ledger_events m where creator_id=u and environment='sandbox';
 select coalesce(sum(greatest(0,(private.sandbox_cashout_merch_source(o.id,q.id)->>'netMinor')::bigint
  -coalesce((select sum(a.amount_minor-coalesce(r.released_minor,0)) from private.sandbox_cashout_merch_allocations a
   join private.sandbox_cashout_executions e on e.id=a.execution_id
   left join private.sandbox_cashout_merch_simulated_returns r on r.execution_id=a.execution_id and r.order_id=a.order_id
   where a.order_id=o.id and e.phase<>'canceled'),0))),0)
 into merch_available from public.merch_orders o where creator_id=u and environment='sandbox';
 available:=available+merch_available;
 if available<p_amount_minor then return jsonb_build_object('ready',false,'reason','sandbox_earnings_insufficient','availableMinor',available,'earningsBasis','sandbox_fixture_deductions_not_actual_fees','environment','test','financialAuthority',false); end if;
 app_fee:=case when p_payout_type='instant' then public.calculate_creator_instant_cashout_fee(p_amount_minor) else 0 end;
 bank:=floor(((p_amount_minor::bigint-app_fee-q.provider_fee_fixed_minor)*10000)::numeric/(10000+q.provider_fee_bps));
 fee:=((bank*q.provider_fee_bps+9999)/10000)+q.provider_fee_fixed_minor;
 if bank<=0 or bank+fee+app_fee<>p_amount_minor then return jsonb_build_object('ready',false,'reason','cashout_exact_fee_quote_unavailable','environment','test','financialAuthority',false); end if;
 return jsonb_build_object('ready',true,'qualificationId',q.id,'operationId',gen_random_uuid(),'grossMinor',p_amount_minor,
 'appFeeMinor',app_fee,'expectedProviderFeeMinor',fee,'bankMinor',bank,'payoutType',p_payout_type,'expiresAt',q.expires_at,
 'providerFeeStatus','contract_quote_not_actual','currency','usd','environment','test','financialAuthority',false,
 'earningsBasis','sandbox_fixture_deductions_not_actual_fees','settlementPolicyVersion',q.settlement_policy_version);
end; $function$

CREATE OR REPLACE FUNCTION public.record_sandbox_creator_cashout_observation(p_request_id uuid, p_dispatch_token uuid, p_facts jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare e private.sandbox_cashout_executions; q private.sandbox_cashout_qualifications; kind text; obj text; status text; hash text;
 allocation record; remaining_fixture_cost integer; retained integer;
begin
 if jsonb_typeof(p_facts) is distinct from 'object' or length(p_facts::text)>12000 then raise exception 'sandbox_observation_invalid'; end if;
 select * into e from private.sandbox_cashout_executions where id=p_request_id;
 if e.id is null then raise exception 'sandbox_cashout_not_found'; end if;
 perform private.lock_sandbox_cashout_creator(e.creator_id);
 select * into e from private.sandbox_cashout_executions where id=p_request_id for update;
 select * into q from private.sandbox_cashout_qualifications where id=e.qualification_id;
 kind:=p_facts->>'kind'; obj:=p_facts->>'objectId'; status:=p_facts->>'status'; hash:=md5(p_facts::text);
 if p_dispatch_token is not null and p_dispatch_token is distinct from e.dispatch_token then raise exception 'sandbox_stale_dispatch_token'; end if;
 if p_facts->>'environment' is distinct from 'test' or p_facts->>'accountId' is distinct from q.account_id
 or p_facts->'amountMinor' is distinct from to_jsonb(e.bank_minor) or obj is null
 then raise exception 'sandbox_observation_binding_invalid'; end if;
 if exists(select 1 from private.sandbox_cashout_observations where execution_id=e.id and facts_hash=hash) then return private.sandbox_cashout_summary(e.id); end if;
 if e.phase in ('canceled','returned') then raise exception 'sandbox_terminal_observation_conflict'; end if;
 if kind='transfer' then
  if obj !~ '^tr_[A-Za-z0-9]+$' or (e.transfer_id is not null and e.transfer_id<>obj)
  or jsonb_typeof(p_facts->'fullyReversed') is distinct from 'boolean'
  then raise exception 'sandbox_transfer_binding_invalid'; end if;
  if e.phase='funding_unknown' and p_facts->'reversedMinor'='0'::jsonb and p_facts->'fullyReversed'='false'::jsonb then
   update private.sandbox_cashout_executions set transfer_id=obj,phase='funded' where id=e.id;
  elsif e.phase='reversal_unknown' and e.returned_minor=e.bank_minor
   and p_facts->'reversedMinor'=to_jsonb(e.bank_minor) and p_facts->'fullyReversed'='true'::jsonb then
   update private.sandbox_cashout_executions set phase='returned' where id=e.id;
  else raise exception 'sandbox_transfer_phase_conflict'; end if;
 elsif kind='payout' then
  if obj !~ '^po_[A-Za-z0-9]+$' or (e.payout_id is not null and e.payout_id<>obj)
   or p_facts->>'destinationId' is distinct from q.destination_id
   or status is null or status not in ('pending','in_transit','paid','failed','canceled')
   or e.phase not in ('payout_unknown','payout_pending','paid','return_pending','return_confirmed','needs_review')
  then raise exception 'sandbox_payout_binding_invalid'; end if;
  -- Paid may later fail; stale pending cannot undo paid/returned evidence.
  if e.phase in ('paid','return_pending','return_confirmed') and status in ('pending','in_transit') then raise exception 'sandbox_payout_regression'; end if;
  if e.phase in ('return_pending','return_confirmed') and status='paid' then raise exception 'sandbox_payout_regression'; end if;
  if e.phase='return_confirmed' and status in ('failed','canceled') then
   -- A late observation without balance proof cannot erase a prior proof.
   null;
  elsif status in ('failed','canceled') and p_facts->'returnedMinor'=to_jsonb(e.bank_minor)
   and p_facts->>'returnTransactionId' ~ '^txn_[A-Za-z0-9]+$' then
   update private.sandbox_cashout_executions set payout_id=obj,phase='return_confirmed',returned_minor=bank_minor where id=e.id;
  else
   update private.sandbox_cashout_executions set payout_id=obj,phase=case status when 'paid' then 'paid'
    when 'failed' then 'return_pending' when 'canceled' then 'return_pending' else 'payout_pending' end where id=e.id;
  end if;
 elsif kind='reversal' then
  if e.phase<>'reversal_unknown' or e.returned_minor is distinct from e.bank_minor
   or obj !~ '^trr_[A-Za-z0-9]+$' or p_facts->>'transferId' is distinct from e.transfer_id
  then raise exception 'sandbox_reversal_binding_invalid'; end if;
  update private.sandbox_cashout_executions set reversal_id=obj,phase='returned' where id=e.id;
 elsif kind='funding_return' then
  if e.phase<>'funding_return_unknown' or e.payout_id is not null or obj !~ '^trr_[A-Za-z0-9]+$'
   or p_facts->>'transferId' is distinct from e.transfer_id or p_facts->>'platformAccountId' is distinct from q.platform_account_id
   or p_facts#>>'{fundingBalance,sourceId}' is distinct from e.transfer_id
   or p_facts#>>'{returnBalance,sourceId}' is distinct from obj
   or p_facts#>'{fundingBalance,amountMinor}' is distinct from to_jsonb(-e.bank_minor)
   or p_facts#>'{returnBalance,amountMinor}' is distinct from to_jsonb(e.bank_minor)
   or p_facts#>>'{fundingBalance,status}' is distinct from 'available' or p_facts#>>'{returnBalance,status}' is distinct from 'available'
   or p_facts#>>'{fundingBalance,currency}' is distinct from 'usd' or p_facts#>>'{returnBalance,currency}' is distinct from 'usd'
   or p_facts#>>'{fundingBalance,type}' is distinct from 'transfer'
   or coalesce(p_facts#>>'{returnBalance,type}','') not in ('transfer_refund','transfer_cancel')
  then raise exception 'sandbox_funding_return_binding_invalid'; end if;
  update private.sandbox_cashout_executions set reversal_id=obj,phase='returned',returned_minor=bank_minor where id=e.id;
 else raise exception 'sandbox_observation_kind_invalid'; end if;
 insert into private.sandbox_cashout_observations values(e.id,hash,p_facts,clock_timestamp());
 -- Explicit fixture economics, not an actual-fee receipt. Return app fee and
 -- principal; retain the immutable simulated provider quote once. This never
 -- marks any public source payable or infers actual provider cost from absence.
 if (select phase from private.sandbox_cashout_executions where id=e.id)='returned' then
  remaining_fixture_cost:=e.expected_provider_fee_minor;
  for allocation in select * from private.sandbox_cashout_allocations where execution_id=e.id order by money_ledger_id loop
   retained:=least(allocation.amount_minor,remaining_fixture_cost); remaining_fixture_cost:=remaining_fixture_cost-retained;
   insert into private.sandbox_cashout_simulated_return_accounting values(e.id,allocation.money_ledger_id,allocation.amount_minor-retained,retained);
  end loop;
  for allocation in select * from private.sandbox_cashout_merch_allocations where execution_id=e.id order by order_id loop
   retained:=least(allocation.amount_minor,remaining_fixture_cost); remaining_fixture_cost:=remaining_fixture_cost-retained;
   insert into private.sandbox_cashout_merch_simulated_returns values(e.id,allocation.order_id,allocation.amount_minor-retained,retained);
  end loop;
 end if;
 return private.sandbox_cashout_summary(e.id);
end; $function$

CREATE OR REPLACE FUNCTION public.request_sandbox_creator_cashout(p_amount_minor integer, p_payout_type text, p_qualification_id uuid, p_operation_id uuid, p_expected_app_fee_minor integer, p_expected_provider_fee_minor integer, p_expected_bank_minor integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare u uuid:=private.sandbox_cashout_current_user(); prior private.sandbox_cashout_executions; quote jsonb;
 new_execution uuid; m record; s jsonb; used bigint; take bigint; remaining bigint:=p_amount_minor;
begin
 if p_operation_id is null or p_qualification_id is null then raise exception 'cashout_request_identity_required'; end if;
 perform private.lock_sandbox_cashout_creator(u);
 select * into prior from private.sandbox_cashout_executions where creator_id=u and operation_id=p_operation_id;
 if prior.id is not null then
  if prior.qualification_id is distinct from p_qualification_id or prior.gross_minor is distinct from p_amount_minor
  or prior.app_fee_minor is distinct from p_expected_app_fee_minor or prior.expected_provider_fee_minor is distinct from p_expected_provider_fee_minor
  or prior.bank_minor is distinct from p_expected_bank_minor
  or not exists(select 1 from private.sandbox_cashout_qualifications where id=prior.qualification_id and payout_type=p_payout_type)
  then raise exception 'cashout_request_replay_conflict'; end if;
  return private.sandbox_cashout_summary(prior.id);
 end if;
 if exists(select 1 from private.sandbox_cashout_executions where creator_id=u and phase not in ('paid','returned','canceled'))
 then raise exception 'sandbox_cashout_already_pending'; end if;
 if exists(select 1 from private.sandbox_cashout_executions where creator_id=u and source_hold and phase<>'canceled')
 then raise exception 'sandbox_source_reconciliation_required'; end if;
 quote:=public.preview_sandbox_creator_cashout(p_amount_minor,p_payout_type);
 if quote->'ready' is distinct from 'true'::jsonb or quote->>'qualificationId' is distinct from p_qualification_id::text
 then raise exception 'sandbox_cashout_quote_unavailable'; end if;
 if quote->'appFeeMinor' is distinct from to_jsonb(p_expected_app_fee_minor)
 or quote->'expectedProviderFeeMinor' is distinct from to_jsonb(p_expected_provider_fee_minor)
 or quote->'bankMinor' is distinct from to_jsonb(p_expected_bank_minor) then raise exception 'cashout_displayed_terms_changed'; end if;
 insert into private.sandbox_cashout_executions(creator_id,originating_session_id,operation_id,qualification_id,gross_minor,app_fee_minor,expected_provider_fee_minor,bank_minor)
 values(u,(auth.jwt()->>'session_id')::uuid,p_operation_id,p_qualification_id,p_amount_minor,p_expected_app_fee_minor,p_expected_provider_fee_minor,p_expected_bank_minor) returning private.sandbox_cashout_executions.id into new_execution;
 for m in select * from public.money_access_ledger_events where creator_id=u and environment='sandbox' order by money_access_ledger_events.created_at,money_access_ledger_events.id loop
  s:=private.sandbox_cashout_source(m.id,p_qualification_id);
  if s is null then continue; end if;
  select coalesce(sum(a.amount_minor-coalesce(r.released_minor,0)),0) into used from private.sandbox_cashout_allocations a join private.sandbox_cashout_executions e on e.id=a.execution_id
   left join private.sandbox_cashout_simulated_return_accounting r on r.execution_id=a.execution_id and r.money_ledger_id=a.money_ledger_id
   where a.money_ledger_id=m.id and e.phase<>'canceled';
  take:=least(remaining,greatest(0,(s->>'netMinor')::bigint-used));
  if take>0 then insert into private.sandbox_cashout_allocations values(new_execution,m.id,take,s->>'sourceHash'); remaining:=remaining-take; end if;
  exit when remaining=0;
 end loop;
 if remaining>0 then
  for m in select * from public.merch_orders where creator_id=u and environment='sandbox' order by merch_orders.created_at,merch_orders.id loop
   s:=private.sandbox_cashout_merch_source(m.id,p_qualification_id);
   if s is null then continue; end if;
   select coalesce(sum(a.amount_minor-coalesce(r.released_minor,0)),0) into used
    from private.sandbox_cashout_merch_allocations a join private.sandbox_cashout_executions e on e.id=a.execution_id
    left join private.sandbox_cashout_merch_simulated_returns r on r.execution_id=a.execution_id and r.order_id=a.order_id
    where a.order_id=m.id and e.phase<>'canceled';
   take:=least(remaining,greatest(0,(s->>'netMinor')::bigint-used));
   if take>0 then insert into private.sandbox_cashout_merch_allocations values(new_execution,m.id,take,s->>'sourceHash'); remaining:=remaining-take; end if;
   exit when remaining=0;
  end loop;
 end if;
 if remaining<>0 then raise exception 'sandbox_earnings_insufficient'; end if;
 return private.sandbox_cashout_summary(new_execution);
end; $function$

CREATE OR REPLACE FUNCTION public.reserve_notification_activity_push(p_event_id uuid, p_lease_token uuid, p_push_token_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare e public.notification_activity_events;b private.room_start_notification_bindings;result jsonb;state text;
begin
  select * into e from public.notification_activity_events where id=p_event_id;
  b:=private.current_room_start_notification_binding(e);
  if b.event_id is null or e.status<>'leased' or e.lease_token is distinct from p_lease_token or e.lease_until<=now()
    then return public.reserve_notification_activity_push_pre_room_start(p_event_id,p_lease_token,p_push_token_id); end if;
  perform 1 from public.watch_party_rooms where party_id=b.party_id for share;
  b:=private.current_room_start_notification_binding(e);
  if b.event_id is null then return public.reserve_notification_activity_push_pre_room_start(p_event_id,p_lease_token,p_push_token_id); end if;
  state:=private.room_start_notification_delivery_state(b);
  if state in ('delivered','pending') then return private.defer_duplicate_room_start(e,state); end if;
  result:=public.reserve_notification_activity_push_pre_room_start(p_event_id,p_lease_token,p_push_token_id);
  if result->>'eligible'='true' then
    insert into private.room_start_notification_deliveries(party_id,room_generation,recipient_user_id,winner_event_id)
      values(b.party_id,b.room_generation,b.recipient_user_id,e.id) on conflict do nothing;
  end if;
  return result;
end $function$

CREATE OR REPLACE FUNCTION public.reserve_notification_activity_push_pre_live_visibility(p_event_id uuid, p_lease_token uuid, p_push_token_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_event public.notification_activity_events; v_plan jsonb; v_token public.user_push_tokens; v_badge bigint;
begin
  select * into v_event from public.notification_activity_events where id=p_event_id for update;
  if not found or v_event.status<>'leased' or v_event.lease_token is distinct from p_lease_token
    or v_event.lease_until<=now() or v_event.materialized_at is null then return '{"eligible":false}'::jsonb; end if;
  v_plan:=private.resolve_notification_activity(v_event);
  if not coalesce((v_plan->>'eligible')::boolean,false) or not coalesce((v_plan->>'push_allowed')::boolean,false)
    then return '{"eligible":false}'::jsonb; end if;
  select * into v_token from public.user_push_tokens where id=p_push_token_id for update;
  if not found or not private.notification_activity_token_current(v_token,v_event.recipient_user_id)
    then return '{"eligible":false}'::jsonb; end if;
  insert into public.notification_activity_pushes(event_id,push_token_id,lease_token,token_fingerprint,status)
    values(v_event.id,v_token.id,p_lease_token,v_token.token_fingerprint,'sending')
    on conflict(event_id,push_token_id) do update set status='sending',lease_token=excluded.lease_token,
      attempts=notification_activity_pushes.attempts+1,retry_after=null,started_at=now(),completed_at=null,
      provider_message_id=null,error_code=null
    where notification_activity_pushes.status='retryable' and notification_activity_pushes.attempts<3
      and notification_activity_pushes.retry_after<=now()
      and notification_activity_pushes.lease_token is distinct from excluded.lease_token
      and notification_activity_pushes.token_fingerprint=excluded.token_fingerprint;
  if not found then return '{"eligible":false}'::jsonb; end if;
  select count(*) into v_badge from public.notifications where user_id=v_event.recipient_user_id
    and read_at is null and dismissed_at is null;
  return jsonb_build_object('eligible',true,'token',v_token.token,'platform',v_token.platform,'badge',v_badge,
    'ttl',greatest(0,least(86400,floor(extract(epoch from (coalesce(v_event.expires_at,now()+interval '1 day')-now())))))::integer,
    'title',v_plan->>'title','body',v_plan->>'body','data',jsonb_strip_nulls(jsonb_build_object(
      'notificationId',v_event.notification_id,'notificationType',v_plan->>'notification_type',
      'category',v_plan->>'category','route',v_plan->>'deep_link','targetRoute',v_plan->>'target_route',
      'targetEntityId',v_plan->>'target_entity_id','targetContext',v_plan->'target_context')));
end $function$

CREATE OR REPLACE FUNCTION public.reserve_notification_activity_push_pre_room_start(p_event_id uuid, p_lease_token uuid, p_push_token_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare result jsonb; recipient uuid; badge bigint;
begin
  result:=public.reserve_notification_activity_push_pre_live_visibility(p_event_id,p_lease_token,p_push_token_id);
  if result->>'eligible' is distinct from 'true' then return result; end if;
  select recipient_user_id into recipient from public.notification_activity_events where id=p_event_id and lease_token=p_lease_token;
  select count(*) into badge from public.notifications n where n.user_id=recipient and n.read_at is null and n.dismissed_at is null
    and (n.notification_type not in ('followed_creator_live','circle_friend_live','live_room_member_joined')
      or coalesce((private.live_notification_read_context(n.id,recipient)->>'allowed')::boolean,false));
  return result||jsonb_build_object('badge',badge);
end $function$
